		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0310_2.html',
		'<p>ויקרא י17: &quot;מַדּוּעַ לֹא אֲכַלְתֶּם אֶת הַחַטָּאת בִּמְקוֹם הַקֹּדֶשׁ כִּי קֹדֶשׁ קָדָשִׁים הִוא וְאֹתָהּ נָתַן לָכֶם לָשֵׂאת אֶת עון הָעֵדָה לְכַפֵּר עֲלֵיהֶם לִפְנֵי יהוה&quot;</p><p>ויקרא י18: &quot;הֵן לֹא הוּבָא אֶת דָּמָהּ אֶל הַקֹּדֶשׁ פְּנִימָה אָכוֹל תֹּאכְלוּ אֹתָהּ בַּקֹּדֶשׁ כַּאֲשֶׁר צִוֵּיתִי&quot;</p><p>ויקרא ו22: &quot;כָּל זָכָר בַּכֹּהֲנִים יֹאכַל אֹתָהּ קֹדֶשׁ קָדָשִׁים הִוא&quot;</p><p>ויקרא ו23: &quot;וְכָל חַטָּאת אֲשֶׁר יוּבָא מִדָּמָהּ אֶל אֹהֶל מוֹעֵד  [אֶל הַקֹּדֶשׁ פְּנִימָה]  לְכַפֵּר בַּקֹּדֶשׁ לֹא תֵאָכֵל בָּאֵשׁ תִּשָּׂרֵף&quot;</p><p>ויקרא י19: &quot;וַיְדַבֵּר אַהֲרֹן אֶל מֹשֶׁה הֵן הַיּוֹם הִקְרִיבוּ אֶת חַטָּאתָם וְאֶת עֹלָתָם לִפְנֵי יהוה וַתִּקְרֶאנָה אֹתִי כָּאֵלֶּה וְאָכַלְתִּי חַטָּאת הַיּוֹם הַיִּיטַב בְּעֵינֵי יהוה&quot; </p><p>ויקרא י20: &quot;וַיִּשְׁמַע מֹשֶׁה וַיִּיטַב בְּעֵינָיו&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-03-28 16:42:59'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

