		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1404_0.html',
		'<p>למי באמת &quot;סמכות חכמים&quot; על פי התורה?</p><p>דברים יז8: &quot;כִּי יִפָּלֵא מִמְּךָ דָבָר לַמִּשְׁפָּט בֵּין דָּם לְדָם בֵּין דִּין לְדִין וּבֵין נֶגַע לָנֶגַע דִּבְרֵי רִיבֹת בִּשְׁעָרֶיךָ וְקַמְתָּ וְעָלִיתָ אֶל הַמָּקוֹם....... אֲשֶׁר יִבְחַר יהוה אֱלֹהֶיךָ בּוֹ&quot; </p><p>דברים יז9: &quot;וּבָאתָ אֶל הַכֹּהֲנִים הַלְוִיִּם וְאֶל הַשֹּׁפֵט אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם וְדָרַשְׁתָּ וְהִגִּידוּ לְךָ אֵת דְּבַר הַמִּשְׁפָּט&quot; </p><p>וְעָלִיתָ אֶל הַמָּקוֹם....... אֲשֶׁר יִבְחַר יהוה אֱלֹהֶיךָ בּוֹ&quot; = &quot;וּבָאתָ אֶל הַכֹּהֲנִים הַלְוִיִּם וְאֶל הַשֹּׁפֵט אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם</p><p> הַכֹּהֲנִים הַלְוִיִּם וְהַשֹּׁפֵט = הם המקום הקדוש אשר בחר אלהים</p><p> בפסוק “וְעָלִיתָ אֶל הַמָּקוֹם אֲשֶׁר יִבְחַר יהוה אֱלֹהֶיךָ בּוֹ” --- בתורת משה איש האלהים המצווה היא שכאשר יש דין קשה מסובך או שנוי במחלוקת — האדם צריך לעלות אל המקום שיהוה בחר בו. בפסוק הבא התורה מפרשת מה הוא “המקום”: “וּבָאתָ אֶל הַכֹּהֲנִים הַלְוִיִּם וְאֶל הַשֹּׁפֵט אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם”. </p><p>כלומר, המקום שיהוה בחר בו אינו רק נקודה גיאוגרפית, אלא המוסד הרוחני‑שיפוטי המוסמך — הכוהנים הלווים והשופט שבאותו הדור. </p><p>הם נחשבים “המקום” מפני שסמכות אלהים ניתנה להם להכריע בדין. לאמור כי רק הם באמת סמכות חכמים הם הַכֹּהֲנִים הַלְוִיִּם וְהַשֹּׁפֵט אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם וְדָרַשְׁתָּ וְהִגִּידוּ לְךָ אֵת דְּבַר הַמִּשְׁפָּט</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-04-29 17:59:27'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

