		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0416_3.html',
		'<p>בבית כנסת בקבלת שבת שרים את השיר &quot;לכה דודי לקראת כלה פני שבת נקבלה&quot;</p><p>אני מזדהה עם רוב מילות השיר אבל את המשפט הזה מהשיר איני יכול לקבל &quot;סוֹף מַעֲשֶׂה בְּמַחֲשָׁבָה תְּחִלָּה&quot;</p><p>ועתה אסביר </p><p>דמיין שאתה נמצא בבית פרטי עם בריכה יושב בגינה ולפתע פתאום התינוק שלך נפל לבריכה בהיסח הדעת</p><p>האם אתה תקפוץ להצילו באינסטינקט טבעי ללא מחשבה או שאתה קודם תחשוב תחילה ......</p><p>אם הבנת את הסיטואציה הזאת אז ברור לך שמשפטי רבני חזל לא נכתבו בקודש ואיני יכול לקבלם</p><p>רבני חזל בדבריהם לא ידעו לחשוב על כל הסיטואציות בחיים זו ההוכחה כי דבריהם לא נכתבו בקודש</p><p>אנא רבותי אל תראו בי קטנוני והבינו כי קודש אמיתי הוא אוניברסלי ומתאים לכל מצב </p><p>קודש אמיתי זה דבר אמת שמתאים לכל סיטואציה ולכל עת וזמן ולא כן רבני חזל</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-06-26 07:53:57'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

