		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2821_2.html',
		'<p>בראשית מח22: &quot;וַאֲנִי נָתַתִּי לְךָ שְׁכֶם אַחַד עַל אַחֶיךָ אֲשֶׁר לָקַחְתִּי מִיַּד הָאֱמֹרִי בְּחַרְבִּי וּבְקַשְׁתִּי&quot;</p><p>אֲשֶׁר לָקַחְתִּי מִיַּד הָאֱמֹרִי בְּחַרְבִּי וּבְקַשְׁתִּי !! ת&quot;י ב\': דִּי שְׁקַלְתִּיהָ מִיַּד אֱמוֹרָאָה בְּצָלוֹתִי וּבְבָעוּתִי. = [וַיִּתְפַּלֵּל אֶל יהוה]</p><p>    </p><p> דברים לג29: &quot;אַשְׁרֶיךָ יִשְׂרָאֵל מִי כָמוֹךָ עַם נוֹשַׁע ביהוה מָגֵן עֶזְרֶךָ וַאֲשֶׁר ***חֶרֶב גַּאֲוָתֶךָ*** וְיִכָּחֲשׁוּ אֹיְבֶיךָ לָךְ וְאַתָּה עַל בָּמוֹתֵימוֹ תִדְרֹךְ&quot;</p><p> </p><p> ישעיהו כז1: &quot;בַּיּוֹם הַהוּא יִפְקֹד יהוה *******בְּחַרְבוֹ הַקָּשָׁה וְהַגְּדוֹלָה וְהַחֲזָקָה******* עַל לִוְיָתָן נָחָשׁ בָּרִחַ וְעַל לִוְיָתָן נָחָשׁ עֲקַלָּתוֹן וְהָרַג אֶת הַתַּנִּין אֲשֶׁר בַּיָּם&quot; </p><p>******* זאת תהיה המלחמה האחרונה.......אשר עם-יהוה יתפלל אל אלהי יעקב ככתוב בְּצָלוֹתִי וּבְבָעוּתִי.*******</p><p>זכריה יב6: &quot;בַּיּוֹם הַהוּא אָשִׂים אֶת אַלֻּפֵי יְהוּדָה כְּכִיּוֹר אֵשׁ בְּעֵצִים וּכְלַפִּיד אֵשׁ בְּעָמִיר וְאָכְלוּ עַל יָמִין וְעַל שְׂמֹאול אֶת כָּל הָעַמִּים סָבִיב וְיָשְׁבָה יְרוּשָׁלַים עוֹד תַּחְתֶּיהָ בִּירוּשָׁלָים&quot;</p><p>זכריה יב7: &quot;וְהוֹשִׁיעַ יהוה אֶת אָהֳלֵי יְהוּדָה בָּרִאשֹׁנָה לְמַעַן לֹא תִגְדַּל תִּפְאֶרֶת בֵּית דָּוִיד וְתִפְאֶרֶת יֹשֵׁב יְרוּשָׁלַים עַל יְהוּדָה&quot;</p><p>זכריה יב8: &quot;בַּיּוֹם הַהוּא יָגֵן יהוה בְּעַד יוֹשֵׁב יְרוּשָׁלַים וְהָיָה הַנִּכְשָׁל בָּהֶם בַּיּוֹם הַהוּא כְּדָוִיד וּבֵית דָּוִיד כֵּאלֹהִים כְּמַלְאַךְ ה\' לִפְנֵיהֶם&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-06-28 03:12:11'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2821_2.html',
		'<p>בראשית מח22: &quot;וַאֲנִי נָתַתִּי לְךָ שְׁכֶם אַחַד עַל אַחֶיךָ אֲשֶׁר לָקַחְתִּי מִיַּד הָאֱמֹרִי בְּחַרְבִּי וּבְקַשְׁתִּי&quot;</p><p>אֲשֶׁר לָקַחְתִּי מִיַּד הָאֱמֹרִי בְּחַרְבִּי וּבְקַשְׁתִּי !! ת&quot;י ב\': דִּי שְׁקַלְתִּיהָ מִיַּד אֱמוֹרָאָה בְּצָלוֹתִי וּבְבָעוּתִי. = [וַיִּתְפַּלֵּל אֶל יהוה]</p><p>דברים לג29: &quot;אַשְׁרֶיךָ יִשְׂרָאֵל מִי כָמוֹךָ עַם נוֹשַׁע ביהוה מָגֵן עֶזְרֶךָ וַאֲשֶׁר ***חֶרֶב גַּאֲוָתֶךָ*** וְיִכָּחֲשׁוּ אֹיְבֶיךָ לָךְ וְאַתָּה עַל בָּמוֹתֵימוֹ תִדְרֹךְ&quot;</p><p>ישעיהו כז1: &quot;בַּיּוֹם הַהוּא יִפְקֹד יהוה *******בְּחַרְבוֹ הַקָּשָׁה וְהַגְּדוֹלָה וְהַחֲזָקָה******* עַל לִוְיָתָן נָחָשׁ בָּרִחַ וְעַל לִוְיָתָן נָחָשׁ עֲקַלָּתוֹן וְהָרַג אֶת הַתַּנִּין אֲשֶׁר בַּיָּם&quot;</p><p>******* זאת תהיה המלחמה האחרונה.......אשר עם-יהוה יתפלל אל אלהי יעקב ככתוב בְּצָלוֹתִי וּבְבָעוּתִי.*******</p><p>זכריה יב6: &quot;בַּיּוֹם הַהוּא אָשִׂים אֶת אַלֻּפֵי יְהוּדָה כְּכִיּוֹר אֵשׁ בְּעֵצִים וּכְלַפִּיד אֵשׁ בְּעָמִיר וְאָכְלוּ עַל יָמִין וְעַל שְׂמֹאול אֶת כָּל הָעַמִּים סָבִיב וְיָשְׁבָה יְרוּשָׁלַים עוֹד תַּחְתֶּיהָ בִּירוּשָׁלָים&quot;</p><p>זכריה יב7: &quot;וְהוֹשִׁיעַ יהוה אֶת אָהֳלֵי יְהוּדָה בָּרִאשֹׁנָה לְמַעַן לֹא תִגְדַּל תִּפְאֶרֶת בֵּית דָּוִיד וְתִפְאֶרֶת יֹשֵׁב יְרוּשָׁלַים עַל יְהוּדָה&quot;</p><p>זכריה יב8: &quot;בַּיּוֹם הַהוּא יָגֵן יהוה בְּעַד יוֹשֵׁב יְרוּשָׁלַים וְהָיָה הַנִּכְשָׁל בָּהֶם בַּיּוֹם הַהוּא כְּדָוִיד וּבֵית דָּוִיד כֵּאלֹהִים כְּמַלְאַךְ יהוה לִפְנֵיהֶם&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-06-28 03:13:44'
		)
		;

SET character_set_client=utf8mb3;
