		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/daian2_0.html',
		'<p>כשאתה נכנס למקלחת בדוש אל תזרים תחילה מים לעבר הראש והפנים</p><p>וכי עליך לחקות את מעשה הטבילה בנהר או אגם בריכה או ים</p><p>לאמור כי תחילה הטה שפופרת צינור המים לעבר הרגליים והשפרץ מים</p><p>אחרי כן בהדרגתיות לעבר הבטן ורק בסוף לעבר הראש והפנים</p><p>--- הרגל זה יגן עליך בזכות הדרגתיות שמונעת שוק-טמפרטורה</p><p>ובגיל מבוגר שוק-טמפרטורה זה דבר מסוכן אשר יש להגן מפניו</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-06-29 17:52:28'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1502_2.html',
		'<p>ספר הנביא שמואל פרק ג כתוב:</p><p>ו וַיְהִי בִּהְיוֹת הַמִּלְחָמָה בֵּין בֵּית שָׁאוּל וּבֵין בֵּית דָּוִד וְאַבְנֵר הָיָה מִתְחַזֵּק בְּבֵית שָׁאוּל.  </p><p>ז וּלְשָׁאוּל פִּלֶגֶשׁ וּשְׁמָהּ רִצְפָּה בַת-אַיָּה וַיֹּאמֶר אֶל-אַבְנֵר מַדּוּעַ בָּאתָה אֶל-פִּילֶגֶשׁ אָבִי.  </p><p>ח וַיִּחַר לְאַבְנֵר מְאֹד עַל-דִּבְרֵי אִישׁ-בֹּשֶׁת וַיֹּאמֶר הֲרֹאשׁ כֶּלֶב אָנֹכִי אֲשֶׁר לִיהוּדָה הַיּוֹם אֶעֱשֶׂה-חֶסֶד עִם-בֵּית שָׁאוּל אָבִיךָ אֶל-אֶחָיו וְאֶל-מֵרֵעֵהוּ וְלֹא הִמְצִיתִךָ בְּיַד-דָּוִד וַתִּפְקֹד עָלַי עֲו‍ֹן הָאִשָּׁה הַיּוֹם.  </p><p>ט כֹּה-יַעֲשֶׂה אֱלֹהִים לְאַבְנֵר וְכֹה יֹסִיף לוֹ  כִּי כַּאֲשֶׁר נִשְׁבַּע יְהוָה לְדָוִד כִּי-כֵן אֶעֱשֶׂה-לּוֹ.  </p><p>י לְהַעֲבִיר הַמַּמְלָכָה מִבֵּית שָׁאוּל וּלְהָקִים אֶת-כִּסֵּא דָוִד עַל-יִשְׂרָאֵל וְעַל-יְהוּדָה מִדָּן וְעַד-בְּאֵר שָׁבַע.  </p><p>יא וְלֹא-יָכֹל עוֹד לְהָשִׁיב אֶת-אַבְנֵר דָּבָר מִיִּרְאָתוֹ אֹתוֹ.  </p><p>-</p><p>אז הנה לכם כמשל הזה</p><p>שמואל ב ג11: &quot;וְלֹא יָכֹל עוֹד לְהָשִׁיב אֶת אַבְנֵר דָּבָר מִיִּרְאָתוֹ אֹתוֹ&quot;</p><p>וזאת הסיבה שהרבנים שותקים מתוך פחד ולא מתוך חכמה</p><p>לכן הם לא עונים לכל הדברים אשר כתבתי להם והוכחתים</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-06-30 08:08:08'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1404_0.html',
		'<p>תהלים פב3: &quot;שִׁפְטוּ דַל וְיָתוֹם עָנִי וָרָשׁ הַצְדִּיקוּ&quot;</p><p>אבל איך נצדיק את הרש אם.......</p><p>משלי י4: &quot;רָאשׁ עֹשֶׂה כַף רְמִיָּה וְיַד חָרוּצִים תַּעֲשִׁיר&quot;</p><p>---------------------------------------------------------</p><p>התשובה היא שהמקרא מבחין בין רָשׁ לבין רָשָׁ-ע.</p><p>רָשׁ הוא אדם חלש, חסר, נזקק — אדם שמעשיו אולי אינם מושלמים, אך הם נובעים ממצוקה ולא מרוע. </p><p>רָשָׁ-ע הוא אדם שמרמה מתוך בחירה מודעת, מתוך כוח, מתוך ניצול — אדם שהפך את המרמה לדרך חיים.</p><p>עתה אספר לכם סיפור אמיתי להבנה</p><p>אתמול בקניון העיר הסתובבה אשה נכה, גמדה, שנראתה גם מוגבלת שכלית. היא פנתה אליי בבקשה לכסף, בטענה שחסר לה לנסיעות. היה ברור לי שמדובר ב“כַּף רְמִיָּה”, </p><p>אך לא שפטתי אותה על פי המעשה בלבד. ראיתי את מצוקתה, את חולשתה, את חוסר יכולתה להתמודד עם החיים כמו אדם רגיל. ריחמתי עליה ונתתי לה כסף כאשר ביקשה</p><p>זה נקרא להצדיק את הרש, גם אם הוא עושה “כַּף רְמִיָּה”, מפני שהמעשה נובע ממצוקה מאומללות ומסכנות ולא מרשעות.</p><p>זה אמנם מקרה יחסית חריג, אך הוא מלמד עיקרון גדול: יש אנשים שהרמייה שלהם אינה ביטוי לרוע, אלא לבקשת עזרה שמגיעה בצורה לא מוצלחת. אותם מצדיקים. להם נותנים צדק של חמלה.</p><p>לעומת זאת, אם יש רב מן הרבנים שעושה “כַּף רְמִיָּה” כדרך יום־יום להתפרנס בכזב, ומבחירה מודעת — זה כבר רָשָׁע אשר יש להרשיעו, ולא “רָשׁ” אשר יש להצדיקו. </p><p>זה ההבדל בין רָשׁ לבין רָשָׁע, כאשר במילה “רָשָׁע” אכן מצויות אותיות “רָשׁ”, אך נוסף להן יסוד של רוע מודע.</p><p>כך מתיישבים שני הפסוקים:</p><p>וככה עושים משפט צדק ואמת</p><p>רָשׁ — מצדיקים מתוך חמלה;</p><p>רָשָׁע — מרשיעים מתוך משפט.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-06-30 11:13:32'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2821_2.html',
		'<p>מלכים א כב17: &quot;וַיֹּאמֶר רָאִיתִי אֶת כָּל יִשְׂרָאֵל נְפֹצִים אֶל הֶהָרִים כַּצֹּאן אֲשֶׁר אֵין לָהֶם רֹעֶה וַיֹּאמֶר יהוה לֹא אֲדֹנִים לָאֵלֶּה יָשׁוּבוּ אִישׁ לְבֵיתוֹ בְּשָׁלוֹם&quot;</p><p>דברי הימים ב יח16: &quot;וַיֹּאמֶר רָאִיתִי אֶת כָּל יִשְׂרָאֵל נְפוֹצִים עַל הֶהָרִים כַּצֹּאן אֲשֶׁר אֵין לָהֶן רֹעֶה וַיֹּאמֶר יהוה לֹא אֲדֹנִים לָאֵלֶּה יָשׁוּבוּ אִישׁ לְבֵיתוֹ בְּשָׁלוֹם&quot;</p><p> זה לא הזמן להנהגה כוחנית עם אויבי ישראל— זה הזמן שכל אדם יחזור לביתו בשלום.</p><p>אני שומע את כל הטיפשים בערוץ 14 שמדברים כוחניות כאשר הם מתעלמים שחצי מהמדינה הם טמאים להטבי&quot;ם וצועדים במצעד גאוה ובמצב זה לא ניתן להצליח במלחמה</p><p>האמינו לי לדיין שם כי אני איש ימין ובעד ארץ ישראל השלמה אך זה לא הזמן להנהגה כוחנית עם אויבי ישראל --- אתם רואים במו עיניכם כי כל יום נופלים חיילים וקצינים חללים </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-01 11:13:54'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0101_23.html',
		'<p>בלוח-דיין = הוא לוח-המקדש = לוח-שמש</p><p>------------------------------------------------------------------------------------</p><p>ראש חודש האביב הוא ראש השנה 9 ימים לפני שיוויון האביב האסטרונומי</p><p>--------------------------------------------------------------------------------</p><p>לאמור כי יום שוויון האביב האסטרונומי בעשור לחודש האביב</p><p>--------------------------------------------------------------------------------</p><p>יום שוויון האביב בין היום והלילה 5 ימים לפני יום השיוויון האסטרונומי</p><p>-------------------------------------------------------------------------------</p><p>היום הארוך ביותר בעשור לחודש הרביעי</p><p>-------------------------------------------------------------------------------</p><p>יום הכפורים 10.7 הוא יום שיוויון הסתיו האסטרונומי</p><p>-------------------------------------------------------------------------------</p><p>חג-הסכות 15.7 הוא יום שיווין הסתיו בין היום והלילה</p><p>-------------------------------------------------------------------------------</p><p>והיום הקצר ביותר הוא העשור לחודש העשירי [10.10]</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-01 16:56:40'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
