		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0101_23.html',
		'<p>בלוח-דיין = הוא לוח-המקדש = לוח-שמש</p><p>------------------------------------------------------------------------------------</p><p>ראש חודש האביב הוא ראש השנה 9 ימים לפני שיוויון האביב האסטרונומי</p><p>--------------------------------------------------------------------------------</p><p>לאמור כי יום שוויון האביב האסטרונומי בעשור לחודש האביב</p><p>--------------------------------------------------------------------------------</p><p>יום שוויון האביב בין היום והלילה 5 ימים לפני יום השיוויון האסטרונומי</p><p>-------------------------------------------------------------------------------</p><p>היום הארוך ביותר בעשור לחודש הרביעי</p><p>-------------------------------------------------------------------------------</p><p>יום הכפורים 10.7 הוא יום שיוויון הסתיו האסטרונומי</p><p>-------------------------------------------------------------------------------</p><p>חג-הסכות 15.7 הוא יום שיווין הסתיו בין היום והלילה</p><p>-------------------------------------------------------------------------------</p><p>והיום הקצר ביותר הוא העשור לחודש העשירי [10.10]</p><p>-------------------------------------------------------------------------------</p><p>-</p><p>-</p><p>-</p><p>סוף דבר</p><p>יום שוויון האביב בין היום והלילה 5 ימים לפני יום שוויון האביב האסטרונומי</p><p>יום שוויון הסתיו בין היום והלילה 5 ימים אחרי יום שוויון הסתיו האסטרונומי</p><p>-</p><p>--------- היום הקצר ביותר בעשור לחודש העשירי</p><p>שוויון האביב האסטרונומי בעשור לחודש הראשון</p><p>------- והיום הארוך ביותר בעשור לחודש הרביעי</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-02 01:35:48'
		)
		;

SET character_set_client=utf8mb3;
