		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2690_2.html',
		'<p>איוב ד7: &quot;זְכָר נָא מִי הוּא נָקִי אָבָד וְאֵיפֹה יְשָׁרִים נִכְחָדוּ&quot;</p><p>זְכָר נָא כי האדם הראשון ביום הבראו היה צדיק וישר</p><p>הוא היה נביא איש-אלהים וכמלך המושל על כל הארץ</p><p>ואם אדם כזה כיצירת אלהים התפתה וחטא מי אנחנו?</p><p>אם גם דוד-המלך משיח אלהים חטא אז מי אנחנו?</p><p>ואם גם שלמה המלך החכם באדם חטא מי אנחנו?</p><p>לאמור כי גם אם אתה נביא ישר ונקי בעיני אלהים</p><p>השמר לך מאד מעיוורון הפשע והחטא שיובילך לאבדון</p><p>עליך לזכור איך אדם קדוש ישר ונקי הלך לאבדון</p><p>לכן .......</p><p>איוב ד7: &quot;זְכָר נָא מִי הוּא נָקִי אָבָד וְאֵיפֹה יְשָׁרִים נִכְחָדוּ&quot;</p><p>אני כותב זאת למען בני-ישראל הקדושים אל תהיו שאננים</p><p>כי גם אם אתם באמת צדיקים אל תאמרו צדיקים אנחנו</p><p>בכל יום יש סכנות לפיתוי וחטא ואין האדם יודע במה יפול</p><p>לכן אל תהיו שאננים העירו רוחכם לעשות צדקה יום יום</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-02 08:14:26'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1404_0.html',
		'<p>https://scontent.ftlv1-1.fna.fbcdn.net/v/t39.30808-6/511295570_10041207625949059_862131084693322071_n.jpg?stp=dst-jpg_tt6&amp;cstp=mx930x523&amp;ctp=s930x523&amp;_nc_cat=100&amp;ccb=1-7&amp;_nc_sid=86c6b0&amp;_nc_ohc=cxJY6V1kv60Q7kNvwGAQ6QH&amp;_nc_oc=Adrspv-YCehhAvqcYRyN6HyIl_0UD-l5StySH1RAiFyKFOVy9iu4KkmZXiCzG6mWkaaXW-GXUOfoDymdKujdnyEW&amp;_nc_zt=23&amp;_nc_ht=scontent.ftlv1-1.fna&amp;_nc_gid=DEmWpcprK78CAG6T9ex_ug&amp;_nc_ss=7b2a8&amp;oh=00_AQBm1h353tTRsARoialMtKBnvRZf_9PJJpDBf-Iy5t43Kg&amp;oe=6A4C5A3C</p><p>דברי הימים א יז6: &quot;בְּכֹל אֲשֶׁר הִתְהַלַּכְתִּי בְּכֹל יִשְׂרָאֵל הֲדָבָר דִּבַּרְתִּי אֶת אַחַד שֹׁפְטֵי יִשְׂרָאֵל אֲשֶׁר צִוִּיתִי לִרְעוֹת אֶת עַמִּי</p><p>יחזקאל לד23: &quot;וַהֲקִמֹתִי עֲלֵיהֶם רֹעֶה אֶחָד וְרָעָה אֶתְהֶן אֵת עַבְדִּי דָוִיד הוּא יִרְעֶה אֹתָם וְהוּא יִהְיֶה לָהֶן לְרֹעֶה&quot;</p><p>ישעיהו טז5: &quot;וְהוּכַן בַּחֶסֶד כִּסֵּא וְיָשַׁב עָלָיו בֶּאֱמֶת בְּאֹהֶל דָּוִד שֹׁפֵט וְדֹרֵשׁ מִשְׁפָּט וּמְהִר צֶדֶק&quot;</p><p> </p><p> </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-02 16:26:35'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1404_0.html',
		'<p>https://scontent.ftlv1-1.fna.fbcdn.net/v/t39.30808-6/511295570_10041207625949059_862131084693322071_n.jpg?stp=dst-jpg_tt6&amp;cstp=mx930x523&amp;ctp=s930x523&amp;_nc_cat=100&amp;ccb=1-7&amp;_nc_sid=86c6b0&amp;_nc_ohc=cxJY6V1kv60Q7kNvwGAQ6QH&amp;_nc_oc=Adrspv-YCehhAvqcYRyN6HyIl_0UD-l5StySH1RAiFyKFOVy9iu4KkmZXiCzG6mWkaaXW-GXUOfoDymdKujdnyEW&amp;_nc_zt=23&amp;_nc_ht=scontent.ftlv1-1.fna&amp;_nc_gid=DEmWpcprK78CAG6T9ex_ug&amp;_nc_ss=7b2a8&amp;oh=00_AQBm1h353tTRsARoialMtKBnvRZf_9PJJpDBf-Iy5t43Kg&amp;oe=6A4C5A3C</p><p>דברי הימים א יז6: &quot;בְּכֹל אֲשֶׁר הִתְהַלַּכְתִּי בְּכֹל יִשְׂרָאֵל הֲדָבָר דִּבַּרְתִּי אֶת אַחַד שֹׁפְטֵי יִשְׂרָאֵל אֲשֶׁר צִוִּיתִי לִרְעוֹת אֶת עַמִּי</p><p>יחזקאל לד23: &quot;וַהֲקִמֹתִי עֲלֵיהֶם רֹעֶה אֶחָד וְרָעָה אֶתְהֶן אֵת עַבְדִּי דָוִיד הוּא יִרְעֶה אֹתָם וְהוּא יִהְיֶה לָהֶן לְרֹעֶה&quot;</p><p>ישעיהו טז5: &quot;וְהוּכַן בַּחֶסֶד כִּסֵּא וְיָשַׁב עָלָיו בֶּאֱמֶת בְּאֹהֶל דָּוִד שֹׁפֵט וְדֹרֵשׁ מִשְׁפָּט וּמְהִר צֶדֶק&quot;</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה         </p>',
		'115934331744503251746',
