		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/daian2_0.html',
		'<p>לכבוד דיין DAIAN SHEM </p><p>שלום </p><p>סיפרו לי שאתה עוזר לפתור צרות של אנשים אז הנה אספר לך</p><p>תשמע מה אני אגיד לך אני בחושך גדול ובמצוקה כלכלית ולא הולך לי בכלום</p><p>השנה הזאת אני מחליף קידומת ואני כבר בן 40 ופשוט לא מסתדר לי דבר</p><p>לא בעבודה בקריירה ולא בזוגיות במשפחה כל מה שאני עושה לא מצליח וכבר איבדתי את הבטחון</p><p>כשאני נפגש עם אנשים כמו למשל בראיון עבודה קולטים מייד שאני בעצבות כי קשה לי לשמוח ונרתעים ממני</p><p>אני יודע שאני מקרה קשה ואם תוכל לעזור לי תבוא עליך ברכה</p><p>בכבוד- פלמוני </p><p>------------------------------------------------------------------------------------------------------------------------</p><p>מענה תשובה מאת דיין הוא דַיָּן שֵׁם</p><p>קראתי את כל דבריך שמעתי וראיתי עונייך</p><p>עתה שמע אתה את אשר אני דובר אליך ולא רק אתה לבדך כי אם כל איש אשר חשוך לו</p><p>קודם כל במיידי הייה צמחוני ואל תאכל בשר ואל תשתה יין --- כל עוד אתה בחושך ודרכך נסתרה</p><p>כעת אתה בחושך ואינך יכול לראות על כן לעת הזאת אני אהיה לך לעיניים</p><p>כי תחילה הארץ הייתה תהו-ובהו וחושך על פני תהום ובמצב כזה אמר אלהים יהי אור</p><p>כי קודם כל צריך לראות באור מה לעשות ומי נגד מי</p><p>תהלים קיב4: &quot;זָרַח בַּחֹשֶׁךְ אוֹר לַיְשָׁרִים חַנּוּן וְרַחוּם וְצַדִּיק&quot; </p><p>אם תהיה אתה איש ישר חַנּוּן וְרַחוּם וְצַדִּיק אז יזרח לך האור גם בחושך אשר נגזר עליך</p><p>ישעיהו נח10: &quot;וְתָפֵק לָרָעֵב נַפְשֶׁךָ וְנֶפֶשׁ נַעֲנָה תַּשְׂבִּיעַ וְזָרַח בַּחֹשֶׁךְ אוֹרֶךָ וַאֲפֵלָתְךָ כַּצָּהֳרָיִם&quot;</p><p>לאמור כי אם אתה תציל עניים ונפש רעבה כבעלי חיים פשוט שים להם צלחת אוכל ומים</p><p>וְזָרַח בַּחֹשֶׁךְ אוֹרֶךָ וַאֲפֵלָתְךָ כַּצָּהֳרָיִם</p><p>אז זכור להיות איש ישר ***חַנּוּן ***וְרַחוּם וְצַדִּיק</p><p>תהלים לז26: &quot;כָּל הַיּוֹם ***חוֹנֵן*** וּמַלְוֶה וְזַרְעוֹ לִבְרָכָה&quot;</p><p>------------------------- אז יחנון אותך אלהים -------------------------</p><p>אני חותם לך בדברי אלהים</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה          </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-03 02:38:05'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/daian.html',
		'<p>איוב כא22: &quot;הַלְאֵל יְלַמֶּד דָּעַת וְהוּא רָמִים יִשְׁפּוֹט&quot; = אני דיין [משרת-יהוה] מלַמֶּד דָּעַת [ דָּעַת-אלהים]</p><p>קהלת יב9: &quot;וְיֹתֵר שֶׁהָיָה קֹהֶלֶת חָכָם עוֹד לִמַּד דַּעַת אֶת הָעָם וְאִזֵּן וְחִקֵּר תִּקֵּן מְשָׁלִים הַרְבֵּה&quot;</p><p>  הרבה יותר מלהיות חכם = זה ללמד דַּעַת אֶת הָעָם = זה &quot;זיכוי הרבים&quot; בשפת הרבנים</p><p>מי אשר דעת-אלהים-לו הוא &quot;מזכה הרבים&quot; האמיתי !!! ואתם אחיי וְנֶחְשַׁב לָכֶם תְּרוּמַתְכֶם</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-05 17:48:30'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

