		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2738_3.html',
		'<p>בראשית ו13: &quot;וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי ***כִּי מָלְאָה הָאָרֶץ חָמָס*** מִפְּנֵיהֶם וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ&quot; </p><p>בראשית ז19: &quot;וְהַמַּיִם גָּבְרוּ מְאֹד מְאֹד עַל הָאָרֶץ ***וַיְכֻסּוּ כָּל הֶהָרִים הַגְּבֹהִים*** אֲשֶׁר תַּחַת כָּל הַשָּׁמָיִם&quot; </p><p>ישעיהו יא9: &quot;לֹא יָרֵעוּ וְלֹא יַשְׁחִיתוּ בְּכָל הַר קָדְשִׁי ***כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יהוה*** כַּמַּיִם לַיָּם מְכַסִּים&quot; </p><p>-------------</p><p>הבעיה  ***כִּי מָלְאָה הָאָרֶץ... חָמָס*** -------------------------------אין רוח אלהים מרחפת על פני המים</p><p>הפתרון ***וַיְכֻסּוּ כָּל הֶהָרִים הַגְּבֹהִים***------------------------------ ממלאים את כל הארץ מים</p><p>התוצאה  ***כִּי מָלְאָה הָאָרֶץ... דֵּעָה אֶת יהוה*** ------------------- עתה הבריכה מלאה היא הברכה</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-06 05:44:51'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

