		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2738_3.html',
		'<p>בראשית ו13: &quot;וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי ***כִּי מָלְאָה הָאָרֶץ חָמָס*** מִפְּנֵיהֶם וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ&quot;</p><p>בראשית ז19: &quot;וְהַמַּיִם גָּבְרוּ מְאֹד מְאֹד עַל הָאָרֶץ ***וַיְכֻסּוּ כָּל הֶהָרִים הַגְּבֹהִים*** אֲשֶׁר תַּחַת כָּל הַשָּׁמָיִם&quot;</p><p>ישעיהו יא9: &quot;לֹא יָרֵעוּ וְלֹא יַשְׁחִיתוּ בְּכָל הַר קָדְשִׁי ***כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יהוה*** כַּמַּיִם לַיָּם מְכַסִּים&quot;</p><p>-------------</p><p>הבעיה ***כִּי מָלְאָה הָאָרֶץ... חָמָס*** -------------------------------אין מים אשר ירחף עליהם אלהים</p><p>הפתרון ***וַיְכֻסּוּ כָּל הֶהָרִים הַגְּבֹהִים***------------------------------ ממלאים את כל הארץ מים</p><p>התוצאה ***כִּי מָלְאָה הָאָרֶץ... דֵּעָה אֶת יהוה*** ------------------- עתה הבריכה מלאה היא הברכה</p><p>---------------------------------------------------------------------------------------------------------------</p><p>עתה אחיי למען תהיה לכם הברכה --- כבריכה המלאה</p><p>פתחו את ראשית היום על הבוקר בטבילה רחצו כל בשרכם במים למען.......</p><p>ישעיהו יא9: &quot;לֹא יָרֵעוּ וְלֹא יַשְׁחִיתוּ בְּכָל הַר קָדְשִׁי ***כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יהוה*** כַּמַּיִם לַיָּם מְכַסִּים&quot;</p><p>חבקוק ב14: &quot;כִּי תִּמָּלֵא הָאָרֶץ לָדַעַת אֶת כְּבוֹד יהוה כַּמַּיִם יְכַסּוּ עַל יָם&quot;</p><p>על כן.......לכבוד מתן תורת משה איש האלהים בכל יום ויום רחץ בשרך במים</p><p>שמות יט14: &quot;וַיֵּרֶד מֹשֶׁה מִן הָהָר אֶל הָעָם וַיְקַדֵּשׁ אֶת הָעָם [=רחץ במים את העם] וַיְכַבְּסוּ שִׂמְלֹתָם&quot;</p><p> וַיְקַדֵּשׁ אֶת הָעָם [=רחץ במים את העם] = כי קידוש בארמית רחצה</p><p>ישעיהו א16: &quot;רַחֲצוּ הִזַּכּוּ הָסִירוּ רֹעַ מַעַלְלֵיכֶם מִנֶּגֶד עֵינָי חִדְלוּ הָרֵעַ&quot;</p><p>זה הדבר אשר ציוה משה איש האלהים וכל עבדי-יהוה</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה         </p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-06 06:25:22'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

