		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2655_5.html',
		'<p></p><p>ישעיהו מג20: &quot;תְּכַבְּדֵנִי חַיַּת הַשָּׂדֶה....... תַּנִּים וּבְנוֹת יַעֲנָה כִּי נָתַתִּי בַמִּדְבָּר מַיִם נְהָרוֹת בִּישִׁימֹן לְהַשְׁקוֹת עַמִּי בְחִירִי&quot;</p><p>שמואל א ב30: &quot;לָכֵן נְאֻם יהוה אֱלֹהֵי יִשְׂרָאֵל אָמוֹר אָמַרְתִּי בֵּיתְךָ וּבֵית אָבִיךָ יִתְהַלְּכוּ לְפָנַי עַד עוֹלָם וְעַתָּה נְאֻם יהוה חָלִילָה לִּי כִּי מְכַבְּדַי אֲכַבֵּד....... וּבֹזַי יֵקָלּוּ&quot;</p><p>***********************************************************תְּכַבְּדֵנִי חַיַּת הַשָּׂדֶה - ומְכַבְּדַי אֲכַבֵּד ***********************************************************</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-07 04:49:45'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t3101_9.html',
		'<p>בראשית ב17: &quot;וּמֵעֵץ הַדַּעַת טוֹב וָרָע....... לֹא תֹאכַל מִמֶּנּוּ כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת&quot;</p><p>דניאל יב4: &quot;וְאַתָּה דָנִיֵּאל סְתֹם הַדְּבָרִים וַחֲתֹם הַסֵּפֶר עַד עֵת קֵץ יְשֹׁטְטוּ רַבִּים וְתִרְבֶּה הַדָּעַת&quot;.......</p><p> וְתִרְבֶּה הַדָּעַת....... והַדַּעַת טוֹב וָרָע....... לאמור כי כתוצאה מכך יתגברו גם הכוחות הטובים וגם הכוחות הרעים </p><p>וזה מה שקורה כבר היום במדינת ישראל על כן הקיטוב רק ילך ויעמיק עד.......</p><p> &quot;כִּי תִּמָּלֵא הָאָרֶץ לָדַעַת אֶת כְּבוֹד יהוה כַּמַּיִם יְכַסּוּ עַל יָם&quot; [חבקוק ב14]</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-07 06:10:51'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

