		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/tora/sdr_mnhigim.html',
		'<p>בהמשך לתגובתי האחרונה משנת 2019</p><p>דברים א13: &quot;הָבוּ לָכֶם אֲנָשִׁים חֲכָמִים וּנְבֹנִים וִידֻעִים לְשִׁבְטֵיכֶם וַאֲשִׂימֵם בְּרָאשֵׁיכֶם&quot;</p><p> חֲכָמִים וּנְבֹנִים וִידֻעִים = אלה צריכים להיות השופטים לאמור בעלי חכמה בינה ודעת</p><p>אך הנביא יש בו את כל ששת תכונות רוח-יהוה לאמור כי הנביא גדול כפליים מהשופט</p><p>[וזאת בהנחה שהשופט אכן ראוי לשלושת התכונות האלה של חכמה בינה ודעת</p><p>כידוע משה לא מצא נבונים ונאלץ להסתפק בשופטים חכמים ובעלי דעת אך לא נבונים                             =[</p><p>ישעיהו יא2: &quot;וְנָחָה עָלָיו רוּחַ יהוה רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יהוה&quot;</p><p>נחמיה ט30: &quot;וַתִּמְשֹׁךְ עֲלֵיהֶם שָׁנִים רַבּוֹת וַתָּעַד בָּם *******בְּרוּחֲךָ = בְּיַד נְבִיאֶיךָ******* וְלֹא הֶאֱזִינוּ וַתִּתְּנֵם בְּיַד עַמֵּי הָאֲרָצֹת&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-07 08:59:23'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
