		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1052_3.html',
		'<p>בין ערל לב לבין ערל בשר</p><p>ערל-לב הוא חסר-לב מי שלבו-רע -- זה ברור</p><p>וערל בשר הוא מי שלא נימול --- גם זה ברור</p><p>ויקרא יב3: &quot;וּבַיּוֹם הַשְּׁמִינִי... יִמּוֹל בְּשַׂר עָרְלָתוֹ&quot;</p><p>בראשית יז12: &quot;וּבֶן שְׁמֹנַת יָמִים... יִמּוֹל לָכֶם כָּל זָכָר לְדֹרֹתֵיכֶם יְלִיד בָּיִת וּמִקְנַת כֶּסֶף מִכֹּל בֶּן נֵכָר אֲשֶׁר לֹא מִזַּרְעֲךָ הוּא&quot; </p><p>ומדוע וּבֶן שְׁמֹנַת יָמִים... יִמּוֹל לָכֶם כָּל זָכָר? להודיעכם.......</p><p>כי בֶן שְׁמֹנַת יָמִים...מלשון שמנ=שמן --------------לאמור כי גם שמן זה ערל בשר ומדוע</p><p>כי משמעות המילה ערלה = היא תוספת מיותרת!!! וגם עודף שומן הוא תוספת מיותרת </p><p>ואם אתה כזה שמן=ערל --------- זה יכול להשפיע לרעה על הלב ------- וזה הקשר בין ערל לב לבין ערל בשר</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-07 12:29:26'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1052_3.html',
		'<p>בין ערל לב לבין ערל בשר</p><p>ערל-לב הוא חסר-לב מי שלבו-רע -- זה ברור</p><p>וערל בשר הוא מי שלא נימול --- גם זה ברור</p><p>ויקרא יב3: &quot;וּבַיּוֹם הַשְּׁמִינִי... יִמּוֹל בְּשַׂר עָרְלָתוֹ&quot;</p><p>בראשית יז12: &quot;וּבֶן שְׁמֹנַת יָמִים... יִמּוֹל לָכֶם כָּל זָכָר לְדֹרֹתֵיכֶם יְלִיד בָּיִת וּמִקְנַת כֶּסֶף מִכֹּל בֶּן נֵכָר אֲשֶׁר לֹא מִזַּרְעֲךָ הוּא&quot;</p><p>ומדוע וּבֶן שְׁמֹנַת יָמִים... יִמּוֹל לָכֶם כָּל זָכָר? להודיעכם.......</p><p>כי בֶן שְׁמֹנַת יָמִים...מלשון שמנ=שמן --------------לאמור כי גם שמן זה ערל בשר ומדוע</p><p>כי משמעות המילה ערלה = היא תוספת מיותרת!!! וגם עודף שומן הוא תוספת מיותרת</p><p>ואם אתה כזה שמן=ערל --------- זה יכול להשפיע לרעה על הלב ------- וזה הקשר בין ערל לב לבין ערל בשר</p><p>------------------------------------------------- </p><p>שבע → שִׁבְעַת מלשון שבע בנקודת השובע ------- משלי יג25: &quot;צַדִּיק אֹכֵל לְשֹׂבַע נַפְשׁוֹ........ וּבֶטֶן רְשָׁעִים תֶּחְסָר&quot; </p><p>ואם אתה אוכל מעבר לנקודת השובע [7] אז אתה [8] אתה שמן=שמונה -----------</p><p>אתה שמן כי אתה ערל-לב ואינך קשוב לנקודת השובע לכן אינך צדיק לשמוע בקול אלהים</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-07 12:48:54'
		)
		;

SET character_set_client=utf8mb3;
