		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/tora/bmdbr/bm-24-17.html',
		'<p></p><p>בספר צוואת לוי בן יעקב כתוב:</p><p>ב) ואז יקים יהוה כוהן חדש אשר לו יגלו כל אמרות יהוה והוא יעשה משפט אמת עלי אדמות במלאת הימים.</p><p>ג) ויעלה כוכבו בשמים ככוכב מלך ....... ויאיר באור הדעת כשמש ליום והוא יתגדל בעולם.</p><p>------- אסטרולגית עולמית בכירה בניתוח המפה האסטרולוגית של מלך המשיח כותבת:</p><p>&quot;מעולם לא ראיתי טרנד אסטרולוגי כל כך חזק לפני כן. לעולם לא תראה עוד אחד מסוגו&quot;</p><p>תהלים יט2: &quot;הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל וּמַעֲשֵׂה יָדָיו מַגִּיד הָרָקִיעַ&quot;</p><p>וגם זה כתוב לאחרית הימים בפרשת גוג מארץ המגוג בספר הנביא</p><p>יחזקאל לט23: &quot;וְיָדְעוּ הַגּוֹיִם כִּי בעונם גָּלוּ בֵית יִשְׂרָאֵל עַל אֲשֶׁר מָעֲלוּ בִי וָאַסְתִּר פָּנַי מֵהֶם וָאֶתְּנֵם בְּיַד צָרֵיהֶם וַיִּפְּלוּ בַחֶרֶב כֻּלָּם&quot;</p><p>כל אשר מעלו ביהוה =  &quot;וָאַסְתִּר פָּנַי מֵהֶם וָאֶתְּנֵם בְּיַד צָרֵיהֶם וַיִּפְּלוּ בַחֶרֶב כֻּלָּם&quot;</p><p>ואחרי כן.......</p><p>יחזקאל לט9: &quot;וְיָצְאוּ יֹשְׁבֵי עָרֵי יִשְׂרָאֵל וּבִעֲרוּ וְהִשִּׂיקוּ בְּנֶשֶׁק וּמָגֵן וְצִנָּה בְּקֶשֶׁת וּבְחִצִּים וּבְמַקֵּל יָד וּבְרֹמַח וּבִעֲרוּ בָהֶם אֵשׁ שֶׁבַע שָׁנִים&quot;</p><p>וְיָצְאוּ יֹשְׁבֵי עָרֵי יִשְׂרָאֵל כל הצדיקים הברורים הדומים לשלוש מאות המלקקים של גדעון ואם אלה תהיה ישועה</p><p>אבל קודם יודע משיח-יהוה כי יש להכריע את אויבי ישראל מבית כי אויבייך מהרסייך ומחריבייך ממך יצאו</p><p>ישעיהו מט17: &quot;מִהֲרוּ בָּנָיִךְ מְהָרְסַיִךְ וּמַחֲרִבַיִךְ מִמֵּךְ יֵצֵאוּ&quot;</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-08 01:35:17'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/tora/bmdbr/bm-24-17.html',
