		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0223_0.html',
		'<p>אני ככל מאכילי בעלי החיים כחתולים עושים זאת באהבה על חשבונם</p><p>ואלה שמבקשים תרומות כסף עושים זאת לפרנסה אין-קשר לצדקה</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-09 11:59:21'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0533_4.html',
		'<p>אני דיין שם = מורה לתורה משה דין</p><p>למדתי תורה על חשבוני ומזמני הפרטי אני מלמד בהתנדבות באתר זה</p><p>אם עולם התורה הוא של תורת אמת תורה כזו תשרוד גם בלי תקציבים</p><p>אם התקציבים של בני הישיבות ייעלמו, יישארו רק מי שלומדים לשמה</p><p>זו נקודה עמוקה:</p><p>אם יום אחד המדינה מפסיקה לממן ישיבות,</p><p>זה לא “חיסול עולם התורה”,</p><p>אלא שינוי תנאים.</p><p>ואז קורה בירור טבעי:</p><p>מי שלומד מתוך אמונה → ימשיך</p><p>מי שלומד מתוך נוחות → יפסיק</p><p>מי שלומד מתוך אידיאל → ימצא דרך</p><p>מי שנשען על תקציב → יחפש מסלול אחר</p><p>זה לא בהכרח טוב או רע —</p><p>זה פשוט חושף את המוטיבציה האמיתית של כל אחד.</p><p>לכן חיסול &quot;עולם התורה&quot; יברר אחת לתמיד מי הוא באמת בן תורה</p><p>המושג &quot;עולם התורה&quot; אינו בפי הפוליטיקאים אלא תקציב כסף לבני הישיבות</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-09 13:18:02'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0533_4.html',
		'<p> אני דיין שם = מורה לתורה משה דין</p><p>למדתי תורה על חשבוני ומזמני הפרטי אני מלמד בהתנדבות באתר זה</p><p>אם עולם התורה הוא של תורת אמת תורה כזו תשרוד גם בלי תקציבים</p><p>אם התקציבים של בני הישיבות ייעלמו, יישארו רק מי שלומדים לשמה</p><p>זו נקודה עמוקה:</p><p>אם יום אחד המדינה מפסיקה לממן ישיבות,</p><p>זה לא “חיסול עולם התורה”,</p><p>אלא שינוי תנאים.</p><p>ואז קורה בירור טבעי:</p><p>מי שלומד מתוך אמונה → ימשיך</p><p>מי שלומד מתוך נוחות → יפסיק</p><p>מי שלומד מתוך אידיאל → ימצא דרך</p><p>מי שנשען על תקציב → יחפש מסלול אחר</p><p>זה לא בהכרח טוב או רע —</p><p>זה פשוט חושף את המוטיבציה האמיתית של כל אחד.</p><p>לכן חיסול &quot;עולם התורה&quot; יברר אחת לתמיד מי הוא באמת בן תורה</p><p>המושג &quot;עולם התורה&quot; אינו בפי הפוליטיקאים אלא תקציב כסף לבני הישיבות</p><p>--------------------------------------------------------------------------------------</p><p>“עולם התורה” בשיח הפוליטי</p><p>זה לא תורה.</p><p>זה לא אמונה.</p><p>זה לא מסירות.</p><p>זה פשוט:</p><p>תקציבי ישיבות</p><p>תמיכות ממשלתיות</p><p>הסכמים קואליציוניים</p><p>כסף לבני ישיבות</p><p>מנגנון תקציבי</p><p>הפוליטיקאים משתמשים בביטוי “עולם התורה” כדי לדבר על כסף, לא על תורה.</p><p>--------------------------------------------------------------------------------------</p><p>לימוד לכבוד התורה</p><p>מסירות נפש</p><p>אהבת התורה</p><p>רצון פנימי</p><p>לא תלוי בתקציבים</p><p>לא תלוי בפוליטיקאים</p><p>לא תלוי בממשלה</p><p>לא תלוי במוסדות</p><p>זה עולם שקיים אלפי שנים — בגלות, בעוני, ברדיפות — והוא ימשיך להתקיים תמיד.</p><p>--------------------------------------------</p><p>סוף דבר</p><p>“עולם התורה” הרוחני לא תלוי במדינה.</p><p>“עולם התורה” הפוליטי הוא שם קוד לתקציבי ישיבות.</p><p>אם התקציבים ייעלמו — עולם התורה האמיתי יישאר.</p><p>מי שלומד לשמה ימשיך; מי שלומד מתוך נוחות ייעלם.</p><p>זה בירור טבעי, לא חיסול.</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-09 13:28:05'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

