		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1117_1.html',
		'<p>משלי י4: &quot;רָאשׁ עֹשֶׂה כַף רְמִיָּה וְיַד חָרוּצִים תַּעֲשִׁיר&quot;</p><p>משלי טו19: &quot;דֶּרֶךְ עָצֵל כִּמְשֻׂכַת חָדֶק וְאֹרַח יְשָׁרִים סְלֻלָה&quot;</p><p>-</p><p>רָאשׁ עֹשֶׂה כַף רְמִיָּה = דֶּרֶךְ עָצֵל כִּמְשֻׂכַת חָדֶק ------- [על כן חסום לו בחיים כי הוא עצל ובראשו חושב כף רמיה]</p><p>וְיַד חָרוּצִים תַּעֲשִׁיר =  וְאֹרַח יְשָׁרִים סְלֻלָה ------------ [הדרך פתוחה בפניך כי אתה ישר וחרוץ וזה העושר האמיתי]</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-10 02:22:45'
		)
		;

