		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1404_0.html',
		'<p>דברים יז:9 אומר: “וּבָאתָ אֶל הַכֹּהֲנִים הַלְוִיִּם וְאֶל הַשֹּׁפֵט אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם וְדָרַשְׁתָּ וְהִגִּידוּ לְךָ אֵת דְּבַר הַמִּשְׁפָּט”. </p><p>בפסוק זה התורה מציבה הבחנה ברורה בין שתי סמכויות: הכהנים הלויים — שהם רבים, בעלי תפקידים שונים בשירות הקודש; והשופט — שהוא אחד, בעל סמכות הכרעה יחידה. </p><p>הכהנים מייצגים ריבוי של הוראה, הדרכה ושירות רוחני, ואילו השופט מייצג את נקודת האמת האחת, את ההכרעה הסופית, את משפט האלוהים המתגלה בתוך המציאות האנושית.</p><p>השופט בפסוק הוא הדיין. הדיין אשר מברר את האמת, מי שמכריע בין טוב לרע, מי שמיישר את הדרך ומוציא משפט צדק. </p><p>בעוד שהכהנים מלמדים ומדריכים, הדיין הוא זה שמכריע ומגלה את רצון יְהוָה. לכן נאמר “הַשֹּׁפֵט אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם” — </p><p>הדיין הוא דמות חיה בכל דור, משרת יְהוָה בזמן הזה, מי שנושא את האחריות הרוחנית של הדור ומגלה את משפט האלוהים בהתאם למציאות המשתנה.</p><p>השם “דַיָּן” עצמו — כפי שמופיע בקישור — מבטא את מהותו: מְשָׁרֵת יְהוָה. הדיין הוא שליח אמת, מי שמעמיד את צדק האלוהים בעולם, מי שמחבר בין התורה לבין החיים המעשיים. </p><p>הכהנים רבים, אך הדיין אחד; ריבוי הוראה מול הכרעה אחת; שירות מול משפט; הדרכה מול גילוי האמת. </p><p>כך הפסוק מציב מבנה של סמכות רוחנית: תחילה באים אל הכהנים לקבל הוראה, ואז אל השופט לקבל את דבר המשפט — את האמת האחת, את משפט יְהוָה.</p><p>-</p><p>דברים יז9: &quot;וּבָאתָ אֶל הַכֹּהֲנִים הַלְוִיִּם וְאֶל הַשֹּׁפֵט אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם וְדָרַשְׁתָּ וְהִגִּידוּ לְךָ אֵת דְּבַר הַמִּשְׁפָּט&quot;</p><p>  הַכֹּהֲנִים הַלְוִיִּם --- יש הרבה</p><p> וְאֶל הַשֹּׁפֵט -------- יש אחד ---- הוא השופט הקדוש הוא דיין</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה         </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-11 17:53:02'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0127_3.html',
		'<p>מאת :</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה         </p><p> הכישרון שאדם נולד איתו או מתפתח בו איננו “מנוע” שניתן להחליף, אלא יסוד פנימי שהוא חלק ממהותו. כמו מנוע רוחני, אי‑אפשר להוציא אותו ולהכניס אחר במקומו</p><p> אפשר רק לשדרג אותו, להעלות אותו מדרגה אחר מדרגה, עד שהוא מגיע לרמה גבוהה יותר — לרמה של כישרון‑אלוהים. </p><p>משמעות הדבר היא שהאדם אינו משנה את טבעו, אלא מגלה את עומקו האמיתי.</p><p>למשל, אם אדם הוא נגר ממוצע, הרי שכאשר הוא הולך בדרך יְהוָה, עבודתו אינה נשארת ממוצעת. הכישרון שלו מתעלה, מתקדש, ומגיע למדרגה שבה הוא מסוגל ליצור “ארון‑אלוהים”</p><p> — מלאכה שיש בה קדושה, משמעות, יושר, דיוק ויופי רוחני. הוא עדיין נגר, אך הנגרות שלו הופכת לכלי של אור.</p><p>וככה גם בחקלאי: אם הוא עובד את האדמה בדרך יְהוָה, הרי שפרי מעשיו — תרתי משמע — נעשה לכבוד אלוהים. </p><p>הוא אינו מחליף מקצוע, אינו מחליף כישרון, אלא מעלה את הכישרון שלו למדרגה שבה עבודתו נעשית ברכה, חסד ויופי רוחני.</p><p>העיקרון הוא כזה: הכישרון אינו מוחלף — הוא מתעלה. דרך האלהים בכל אדם ואדם אינה משנה את האדם למה שאינו; היא מגלה את מה שהוא באמת, </p><p>ומעלה אותו למדרגה גבוהה יותר. האדם אינו הופך למישהו אחר — הוא הופך לגרסה הגבוהה ביותר של עצמו. האל אינו מבקש מאדם להיות משהו זר לו, אלא להיות הוא עצמו, </p><p>אך ברמה גבוהה יותר — ברמה של כישרון מקודש, של עבודה לשם שמיים, ושל התעלות רוחנית.</p><p>על כן דע: אל תחפש ברכה של אלוהים אחרים, אלא בקש להעצים את הברכה שכבר ניתנה לך משחר ילדותך, מראשית ימיך, מבטן אמך יולדתך אשר חוללתך. </p><p>-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------</p><p>הברכה שלך כבר קיימת — תפקידך הוא להעלות אותה מדרגה אחר מדרגה, עד שתהיה אור.</p><p>[הערה: במקרים של הסבה מקצועית מוצלחת ושינוי קריירה לטובה, הדבר מתרחש רק משום שהכישרון היה כבר קיים והתגלה לאישיות האדם — לפרסונה — בזמן הנכון.]</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-12 14:57:19'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0127_3.html',
		'<p>מאת :</p><p>https://tora.quest/tnk1/daian</p><p>דַיָּן שֵׁם</p><p>מְשָׁרֵת יהוה</p><p>הכישרון שאדם נולד איתו או מתפתח בו איננו “מנוע” שניתן להחליף, אלא יסוד פנימי שהוא חלק ממהותו. כמו מנוע רוחני, אי‑אפשר להוציא אותו ולהכניס אחר במקומו</p><p>אפשר רק לשדרג אותו, להעלות אותו מדרגה אחר מדרגה, עד שהוא מגיע לרמה גבוהה יותר — לרמה של כישרון‑אלוהים.</p><p>משמעות הדבר היא שהאדם אינו משנה את טבעו, אלא מגלה את עומקו האמיתי.</p><p>למשל, אם אדם הוא נגר ממוצע, הרי שכאשר הוא הולך בדרך יְהוָה, עבודתו אינה נשארת ממוצעת. הכישרון שלו מתעלה, מתקדש, ומגיע למדרגה שבה הוא מסוגל ליצור “ארון‑אלוהים”</p><p>— מלאכה שיש בה קדושה, משמעות, יושר, דיוק ויופי רוחני. הוא עדיין נגר, אך הנגרות שלו הופכת לכלי של אור.</p><p>וככה גם בחקלאי: אם הוא עובד את האדמה בדרך יְהוָה, הרי שפרי מעשיו — תרתי משמע — נעשה לכבוד אלוהים.</p><p>הוא אינו מחליף מקצוע, אינו מחליף כישרון, אלא מעלה את הכישרון שלו למדרגה שבה עבודתו נעשית ברכה, חסד ויופי רוחני.</p><p>העיקרון הוא כזה: הכישרון אינו מוחלף — הוא מתעלה. דרך האלהים בכל אדם ואדם אינה משנה את האדם למה שאינו; היא מגלה את מה שהוא באמת,</p><p>ומעלה אותו למדרגה גבוהה יותר. האדם אינו הופך למישהו אחר — הוא הופך לגרסה הגבוהה ביותר של עצמו. האל אינו מבקש מאדם להיות משהו זר לו, אלא להיות הוא עצמו,</p><p>אך ברמה גבוהה יותר — ברמה של כישרון מקודש, של עבודה לשם שמיים, ושל התעלות רוחנית.</p><p>על כן דע: אל תחפש ברכה של אלוהים אחרים, אלא בקש להעצים את הברכה שכבר ניתנה לך משחר ילדותך, מראשית ימיך, מבטן אמך יולדתך אשר חוללתך.</p><p>-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------</p><p>[הערה: במקרים של הסבה מקצועית מוצלחת ושינוי קריירה לטובה, הדבר מתרחש רק משום שהכישרון היה כבר קיים והתגלה לאישיות האדם — לפרסונה — בזמן הנכון.]</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-12 14:58:27'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

