		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0127_3.html',
		'<p>מאת :</p><p>https://tora.quest/tnk1/daian</p><p>דַיָּן שֵׁם</p><p>מְשָׁרֵת יהוה</p><p>הכישרון שאדם נולד איתו או מתפתח בו איננו “מנוע” שניתן להחליף, אלא יסוד פנימי שהוא חלק ממהותו. כמו מנוע רוחני, אי‑אפשר להוציא אותו ולהכניס אחר במקומו</p><p>אפשר רק לשדרג אותו, להעלות אותו מדרגה אחר מדרגה, עד שהוא מגיע לרמה גבוהה יותר — לרמה של כישרון‑אלוהים.</p><p>משמעות הדבר היא שהאדם אינו משנה את טבעו, אלא מגלה את עומקו האמיתי.</p><p>למשל, אם אדם הוא נגר ממוצע, הרי שכאשר הוא הולך בדרך יְהוָה, עבודתו אינה נשארת ממוצעת. הכישרון שלו מתעלה, מתקדש, ומגיע למדרגה שבה הוא מסוגל ליצור “ארון‑אלוהים”</p><p>— מלאכה שיש בה קדושה, משמעות, יושר, דיוק ויופי רוחני. הוא עדיין נגר, אך הנגרות שלו הופכת לכלי של אור.</p><p>וככה גם בחקלאי: אם הוא עובד את האדמה בדרך יְהוָה, הרי שפרי מעשיו — תרתי משמע — נעשה לכבוד אלוהים.</p><p>הוא אינו מחליף מקצוע, אינו מחליף כישרון, אלא מעלה את הכישרון שלו למדרגה שבה עבודתו נעשית ברכה, חסד ויופי רוחני.</p><p>העיקרון הוא כזה: הכישרון אינו מוחלף — הוא מתעלה. דרך האלהים בכל אדם ואדם אינה משנה את האדם למה שאינו; היא מגלה את מה שהוא באמת,</p><p>ומעלה אותו למדרגה גבוהה יותר. האדם אינו הופך למישהו אחר — הוא הופך לגרסה הגבוהה ביותר של עצמו. האל אינו מבקש מאדם להיות משהו זר לו, אלא להיות הוא עצמו,</p><p>אך ברמה גבוהה יותר — ברמה של כישרון מקודש, של עבודה לשם שמיים, ושל התעלות רוחנית.</p><p>על כן דע: אל תחפש ברכה של אלוהים אחרים, אלא בקש להעצים את הברכה שכבר ניתנה לך משחר ילדותך, מראשית ימיך, מבטן אמך יולדתך אשר חוללתך.</p><p>-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------</p><p>בעתיד, באחרית הימים, כאשר אֱלֹהֵי יִשְׂרָאֵל ישפוך את רוחו על בניו־עבדיו, אז כל אחד יהיה נביא בתחומו. כל איש ואיש יהיה אמנם בעל כישרון אחר מרעהו, אך ברמה של כישרון‑אלוהים. </p><p>אז יהיו כולם כישרונות ברוכי אלוהים — כל אחד יאיר בתחומו, וכל הכישרונות יתעלו ויתקדשו עד שיהיו כולם אור אחד גדול. וכעת אתה בני אמליץ לך ללכת להתנדב על פי כשרון לבך</p><p>[הערה: במקרים של הסבה מקצועית מוצלחת ושינוי קריירה לטובה, הדבר מתרחש רק משום שהכישרון היה כבר קיים והתגלה לאישיות האדם — לפרסונה — בזמן הנכון.]</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-12 15:14:27'
		)
		;

