		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0143_0.html',
		'<p> המעשה הפיזי של האדם הוא חשוב מאד אך כוחו מוגבל. </p><p>אבל הדיבור, הכוונה, התפילה, הברכה — אלו כוחות שאין להם גבול. </p><p>אדם יכול לתת מטבע לצדקה, אך בדיבור אחד של אמת, של חסד, של תפילה</p><p> רוח אדם כזה תאיר לבבות תשנה מציאות ותמלא ים שלם של ברכה.</p><p>-</p><p>לאדם הצדקה המעשית שלו היא טיפה אך הצדקה הרוחנית היא ים.</p><p>כמה כבר בן-אדם יכול לעשות צדקה באופן מעשי הלא זה טיפה בים</p><p>אבל הצדיק ברוח בדבריו בהבל פיו יכול לחולל פלאים ולמלא ים שלם</p><p>על כן כתוב.......</p><p>תהלים לג6: &quot;בִּדְבַר יהוה שָׁמַיִם נַעֲשׂוּ וּבְרוּחַ פִּיו כָּל צְבָאָם&quot;</p><p>על כן ציוה .......</p><p>דברים ל14: &quot;כִּי קָרוֹב אֵלֶיךָ הַדָּבָר מְאֹד בְּפִיךָ וּבִלְבָבְךָ לַעֲשֹׂתוֹ&quot;</p><p>******* מי יתן בְּפִיךָ לשון צדיקים וּבִלְבָבְךָ אמת *******</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-12 16:53:25'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

