		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t26b9_1.html',
		'<p>אח שלי הלא אתה תלמיד חכם כמוני ואנחנו כעת בימי ספר המלכים אז שמע איזה קטע</p><p>אתה זוכר שפרסמתי מודעה בבית ספר שלנו שדרוש ר&quot;מ [רב מלמד] לקהילה שלנו</p><p>אז בא איזה אחד עלאק נביא </p><p>אני שואל אותו איך קוראים לך אומר לי אליהו</p><p>איפה אתה גר אומר אני מתושבי גלעד</p><p>אני שואל אותו אתה נשוי אומר לא! לא התחתנתי </p><p>אני שואל אותו מי זה הרב שלך אומר אין לי רב</p><p>בקיצור הבנתי שזה עוד מתחזה לרב וזרקתי אותו לכל הרוחות</p><p>רבותינו כבר אמרו</p><p>מי שאין לו רב</p><p>מי שלא נשוי </p><p>אחד כזה לא יהיה רב בבית ספרנו</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-13 01:28:07'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/ljon_jorj_nzr1_0.html',
		'<p>מאת:</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה         </p><p>בית ספר לנזירים ונביאים</p><p>יש ללכת לישון מוקדם כדי שתוכל גם להתעורר מוקדם כשעה לפני עלות השחר [ולא בנץ]</p><p>וזאת כדי שתוכל להספיק לקום להתרחץ לקרוא פרק תהילים ואז לשתות כוס מלאה מים</p><p>בזאת הברכה.......</p><p>בראשית א2: &quot;וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם&quot; </p><p>כי כל עוד חושך לפני השחר וברכת  וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם</p><p>זה המסר כדעת-אלהים שיתמוך בך לראות בחושך תרתי משמע וזה מדרכי הנביא הקדוש</p><p>ישעיהו מה3: &quot;וְנָתַתִּי לְךָ אוֹצְרוֹת חֹשֶׁךְ וּמַטְמֻנֵי מִסְתָּרִים לְמַעַן תֵּדַע כִּי אֲנִי יהוה הַקּוֹרֵא בְשִׁמְךָ אֱלֹהֵי יִשְׂרָאֵל&quot;</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-13 02:24:59'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/ljon_jorj_nzr1_0.html',
		'<p>מאת:</p><p>https://tora.quest/tnk1/daian</p><p>דַיָּן שֵׁם</p><p>מְשָׁרֵת יהוה</p><p>בית ספר לנזירים ונביאים</p><p>יש ללכת לישון מוקדם כדי שתוכל גם להתעורר מוקדם כשעה לפני עלות השחר [ולא בנץ]</p><p>ככתוב בספר משלי לא15: &quot;וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ&quot;</p><p>וזאת כדי שתוכל להספיק לקום להתרחץ לקרוא פרק תהילים ואז לשתות כוס מלאה מים</p><p>בזאת הברכה.......</p><p>בראשית א2: &quot;וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם&quot;</p><p>כי כל עוד חושך לפני השחר וברכת וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם</p><p>זה המסר כדעת-אלהים שיתמוך בך לראות בחושך תרתי משמע וזה מדרכי הנביא הקדוש</p><p>ישעיהו מה3: &quot;וְנָתַתִּי לְךָ אוֹצְרוֹת חֹשֶׁךְ וּמַטְמֻנֵי מִסְתָּרִים לְמַעַן תֵּדַע כִּי אֲנִי יהוה הַקּוֹרֵא בְשִׁמְךָ אֱלֹהֵי יִשְׂרָאֵל&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-13 02:26:39'
		)
		;

