		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/ljon_jorj_nzr1_0.html',
		'<p>מאת:</p><p>https://tora.quest/tnk1/daian</p><p>דַיָּן שֵׁם</p><p>מְשָׁרֵת יהוה</p><p>בית ספר לנזירים ונביאים</p><p>יש ללכת לישון מוקדם כדי שתוכל גם להתעורר מוקדם כשעה לפני עלות השחר [ולא בנץ]</p><p>ככתוב בספר משלי לא15: &quot;וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ&quot;</p><p>וזאת כדי שתוכל להספיק לקום להתרחץ לקרוא פרק תהילים ואז לשתות כוס מלאה מים</p><p>בזאת הברכה.......</p><p>בראשית א2: &quot;וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם&quot;</p><p>כי כל עוד חושך לפני השחר וברכת וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם</p><p>זה המסר כדעת-אלהים שיתמוך בך לראות בחושך תרתי משמע וזה מדרכי הנביא הקדוש</p><p>ישעיהו מה3: &quot;וְנָתַתִּי לְךָ אוֹצְרוֹת חֹשֶׁךְ וּמַטְמֻנֵי מִסְתָּרִים לְמַעַן תֵּדַע כִּי אֲנִי יהוה הַקּוֹרֵא בְשִׁמְךָ אֱלֹהֵי יִשְׂרָאֵל&quot;</p><p>[כעת השעה 05:30 בבקר וכבר התרחצתי והתפללתי שתיתי מים ונתתי אוכל לבעלי חיים]</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-13 02:29:13'
		)
		;

