		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t26b9_1.html',
		'<p>מה שלומך חייל בודד שמעתי שנסעת לאומן עתה ספר איך היה בראש השנה</p><p>מה אני אגיד לך היה רע מאד חוייה קשה ובלתי נסבלת</p><p>למה מה קרה ספר</p><p>ובכן איך שהמטוס נחת ראיתי מלא ערבים ולא היה שום בית כנסת</p><p>בפעם הבאה אני לא אקשיב למנטרה של החסידים עומאן עומאן ראש השנה</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-17 08:11:10'
		)
		;

