		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0218_5.html',
		'<p>ישעיהו מא26: </p><p>&quot;מִי הִגִּיד מֵרֹאשׁ וְנֵדָעָה וּמִלְּפָנִים וְנֹאמַר צַדִּיק אַף אֵין מַגִּיד אַף אֵין מַשְׁמִיעַ אַף אֵין שֹׁמֵעַ אִמְרֵיכֶם&quot;</p><p>מִי הִגִּיד מֵרֹאשׁ --- תרתי משע</p><p>1. מִי הִגִּיד מֵרֹאשׁ = מי הודיע מראשית מתחילה</p><p>2. מִי הִגִּיד מֵרֹאשׁ = מהשכל בראשו ולא מלבו</p><p>------------------------------------------</p><p>1. מִי הִגִּיד מֵרֹאשׁ = מי הודיע מראשית, מתחילה</p><p>זו המשמעות הפשוטה:</p><p>“מֵרֹאשׁ” = מן ההתחלה</p><p>מי יכול להודיע מראש מה יקרה?</p><p>מי יכול לתת נבואה אמיתית לפני שהדבר מתרחש?</p><p>ישעיהו מדגיש: אין אדם שיכול לעשות זאת.</p><p>2. מִי הִגִּיד מֵרֹאשׁ = מי אמר עתידות מתוך הראש (השכל), ולא מהלב</p><p>זו משמעות דרשנית/פרשנית:</p><p>“מֵרֹאשׁ” = מן הראש, כלומר מן השכל</p><p>מי יכול לגלות דבר אמיתי מתוך שכל צלול ?</p><p>הנביא בעצם מבקר את “נביאי השקר” שאומרים דברים מהלב, מהדמיון,מביאים מידע ממקור זר ולא משכלם או מהאמת.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-17 13:19:37'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

