		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0231_0.html',
		'<p>לכבוד שבת קודש</p><p>ערכתם ביום ששי שולחן לכבוד שבת ?? [הנחתם מפה ועליה סכו&quot;ם וחלות]</p><p>אל תאכלו כל דבר מאומה על שולחן זה עד שתעשו את הקידוש עם הברכה</p><p>-</p><p>כשערכתם את השולחן הוא כבר “כלי קודש”, ולכן הקידוש הוא הפתיחה הרשמית של הסעודה.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-17 13:46:11'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2690_2.html',
		'<p>לפני עשר שנים בשנת 2016 כתבתי כדברים הבאים</p><p>מלכים א ג9: &quot;וְנָתַתָּ לְעַבְדְּךָ לֵב שֹׁמֵעַ לִשְׁפֹּט אֶת עַמְּךָ לְהָבִין בֵּין טוֹב לְרָע כִּי מִי יוּכַל לִשְׁפֹּט אֶת עַמְּךָ הַכָּבֵד הַזֶּה&quot;</p><p>ירמיהו כד7: &quot;וְנָתַתִּי לָהֶם לֵב לָדַעַת אֹתִי כִּי אֲנִי יהוה וְהָיוּ לִי לְעָם וְאָנֹכִי אֶהְיֶה לָהֶם לֵאלֹהִים כִּי יָשֻׁבוּ אֵלַי בְּכָל לִבָּם&quot;</p><p>******************************************* לֵב לָדַעַת = לֵב שֹׁמֵעַ *******************************************</p><p>-----------------------------------------------------------------------------------------------------------------------------</p><p>ובכל זאת יש הבדל קטן כי...</p><p>לב לדעת = לב יודע מרת נפשו שעבר גבורות ככתוב: כָּל מִשְׁבָּרֶיךָ וְגַלֶּיךָ עָלַי עָבָרוּ</p><p>לב שומע = זה לב חכם לב מתקדם לב של מלך שופט לב שחש ומרגיש את הכל</p><p>-</p><p>אם לב לדעת זה של צדיק</p><p>אז לב שומע של מלך צדיק ------- והוא הלב שהיה לשלמה המלך </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-17 14:41:58'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

