		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2614_0.html',
		'<p>בעת זבח הבקר או הצאן למשל כשאוכלים שווארמה עגל או שיפוד כבש</p><p>יש לקרוא ליהוה לבקשו בכל לב!!! אבל אם חלילה אתם רשעים בעיני אלהים</p><p>ברשעות שום דבר לא יעזור גם אם תהיה בשיפודייה כל יום</p><p>הושע ה6: &quot;בְּצֹאנָם וּבִבְקָרָם יֵלְכוּ לְבַקֵּשׁ אֶת יהוה וְלֹא יִמְצָאוּ חָלַץ מֵהֶם&quot;</p><p>------------------------------------------------------------------------------------</p><p>האדם יכול לשחוט בהמה לעשות בשר על האש לערוך שולחן —</p><p>אבל הוא אינו יכול &quot;לשחוט&quot; את לבו. אלא &quot;לשחוט&quot; את יצר הרע</p><p>הלב איננו בהמה, איננו חומר, איננו גוף.</p><p>הלב הוא נשמה בתוך גוף, והוא הקרבן האמיתי שהאדם מביא לפני יהוה.</p><p>על כן אמר דויד המלך משיח אלהים.......</p><p>תהלים נא19: &quot;זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה&quot;</p><p>הקרבן האמיתי הוא לא הבשר —</p><p>אלא הלב הנשבר, הלב הפתוח, הלב המבקש.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-17 15:53:17'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

