		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0231_0.html',
		'<p>ישעיהו נח13: &quot;אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶךָ עֲשׂוֹת חֲפָצֶיךָ בְּיוֹם קָדְשִׁי וְקָרָאתָ לַשַּׁבָּת עֹנֶג לִקְדוֹשׁ יהוה מְכֻבָּד וְכִבַּדְתּוֹ מֵעֲשׂוֹת דְּרָכֶיךָ מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר&quot;  </p><p>1.וְקָרָאתָ לַשַּׁבָּת  = כינית את השבת בשם --- עונג לִקְדוֹשׁ יהוה מְכֻבָּד</p><p>2. וְקָרָאתָ לַשַּׁבָּת = קראת לה בואי שבת מלכתא --- בעת קבלת השבת</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-18 17:50:40'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/ljon_jorj_nzr1_0.html',
		'<p>https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה   </p><p>-</p><p>בית ספר לנזירים ונביאים</p><p>     </p><p>את החזון כאהבת אלהים מבקשים  חֶזְיוֹן לַיְלָה  טרם נרדמת בשנתך  עֲלֵי מִשְׁכָּב  </p><p>שיר השירים ג1: &quot;עַל מִשְׁכָּבִי....... בַּלֵּילוֹת בִּקַּשְׁתִּי אֵת שֶׁאָהֲבָה נַפְשִׁי בִּקַּשְׁתִּיו וְלֹא מְצָאתִיו&quot;</p><p>איוב לג15: &quot;בַּחֲלוֹם חֶזְיוֹן לַיְלָה בִּנְפֹל תַּרְדֵּמָה עַל אֲנָשִׁים בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב&quot;.......</p><p>שמואל א ג5: &quot;וַיָּרָץ אֶל עֵלִי וַיֹּאמֶר הִנְנִי כִּי קָרָאתָ לִּי וַיֹּאמֶר לֹא קָרָאתִי שׁוּב שְׁכָב וַיֵּלֶךְ וַיִּשְׁכָּב&quot;.......</p><p>שמואל א ג6: &quot;וַיֹּסֶף יהוה קְרֹא עוֹד שְׁמוּאֵל וַיָּקָם שְׁמוּאֵל וַיֵּלֶךְ אֶל עֵלִי וַיֹּאמֶר הִנְנִי כִּי קָרָאתָ לִי וַיֹּאמֶר לֹא קָרָאתִי בְנִי שׁוּב שְׁכָב&quot;.......</p><p>------- ובשפה ארמית כתוב...-------</p><p>דניאל ב28: &quot;בְּרַם אִיתַי אֱלָהּ בִּשְׁמַיָּא גָּלֵא רָזִין וְהוֹדַע לְמַלְכָּא נְבוּכַדְנֶצַּר מָה דִּי לֶהֱוֵא בְּאַחֲרִית יוֹמַיָּא חֶלְמָךְ וְחֶזְוֵי רֵאשָׁךְ עַל מִשְׁכְּבָךְ....... דְּנָה הוּא&quot; </p><p>דניאל ב29: &quot;אנתה[אַנְתְּ] מַלְכָּא רַעְיוֹנָךְ עַל מִשְׁכְּבָךְ....... סְלִקוּ מָה דִּי לֶהֱוֵא אַחֲרֵי דְנָה וְגָלֵא רָזַיָּא הוֹדְעָךְ מָה דִי לֶהֱוֵא&quot; </p><p>דניאל ד2: &quot;חֵלֶם חֲזֵית וִידַחֲלִנַּנִי וְהַרְהֹרִין עַל מִשְׁכְּבִי....... וְחֶזְוֵי רֵאשִׁי יְבַהֲלֻנַּנִי&quot; </p><p>דניאל ד7: &quot;וְחֶזְוֵי רֵאשִׁי עַל מִשְׁכְּבִי....... חָזֵה הֲוֵית וַאֲלוּ אִילָן בְּגוֹא אַרְעָא וְרוּמֵהּ שַׂגִּיא&quot; </p><p>דניאל ד10: &quot;חָזֵה הֲוֵית בְּחֶזְוֵי רֵאשִׁי עַל מִשְׁכְּבִי....... וַאֲלוּ עִיר וְקַדִּישׁ מִן שְׁמַיָּא נָחִת&quot; </p><p>דניאל ז1: &quot;בִּשְׁנַת חֲדָה לְבֵלְאשַׁצַּר מֶלֶךְ בָּבֶל דָּנִיֵּאל חֵלֶם חֲזָה וְחֶזְוֵי רֵאשֵׁהּ עַל מִשְׁכְּבֵהּ....... בֵּאדַיִן חֶלְמָא כְתַב רֵאשׁ מִלִּין אֲמַר&quot;</p><p>         </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-18 18:13:30'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2821_2.html',
		'<p>במדבר לב6: &quot;וַיֹּאמֶר מֹשֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן הַאַחֵיכֶם יָבֹאוּ לַמִּלְחָמָה וְאַתֶּם תֵּשְׁבוּ פֹה&quot;</p><p>ארץ ישראל ארץ מלחמות היא !! ואם ידעו לנתב המלחמה לכבוד אלהים אז יבוא שלום</p><p>--------------------------------------------------------------------------------------------------</p><p>פרוש לבאר</p><p>כִּי לֹא לָכֶם הַמִּלְחָמָה כִּי לֵאלֹהִים --- כִּי מֵהָאֱלֹהִים הַמִּלְחָמָה</p><p>שמות יז16: &quot;וַיֹּאמֶר כִּי יָד עַל כֵּס יָהּ מִלְחָמָה ליהוה בַּעֲמָלֵק מִדֹּר דֹּר&quot;</p><p> מִלְחָמָה ליהוה בַּעֲמָלֵק מִדֹּר דֹּר = היא מלחמה לנצח של רוח אלהים</p><p>הארץ הזו תמיד דרשה מאדם לב חזק</p><p>הארץ הזו תמיד דרשה מאבק פנימי</p><p>הארץ הזו תמיד דרשה עמידה מול קושי</p><p>הארץ הזו תמיד דרשה אחריות הדדית</p><p>המלחמות של המקרא אינן רק מלחמות פיזיות.</p><p>הן מלחמות של תכונות אלהים:</p><p>מוסר</p><p>צדק</p><p>אמונה</p><p>אמת</p><p>לב</p><p>שליחות</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-18 18:30:24'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0517_1.html',
		'<p>תהלים כה9: &quot;יַדְרֵךְ עֲנָוִים בַּמִּשְׁפָּט וִילַמֵּד עֲנָוִים דַּרְכּוֹ&quot;</p><p>אני דיין מדריך עֲנָוִים בַּמִּשְׁפָּט   ומלַמֵּד עֲנָוִים דַּרְכּי</p><p>אם אתם ענוים יראי-אלהים בואו לשמוע תורת-משה-דַיָּן</p><p>מאתי מורה לתורה משה דַיָּן </p><p>https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם                </p><p>       מְשָׁרֵת יהוה          </p>',
		'115934331744503251746',
