		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/daian2_0.html',
		'<p>אחיי בני ישראל אתם העֲנָוִים יראי-האלהים אליכם אקרא</p><p>שמעו בקולי כדברים הבאים.......</p><p>בעת קומכם מטומאת המיטה הסירו קודם את טומאת המיתה</p><p>לאמור קודם כל רחצו במים את כל בשרכם בטרם תתפללו</p><p>כן בני אל תתפלל &quot;מודה אני לפניך&quot; בטרם רחצת במים את כל בשרך</p><p>איך תתפלל כשטומאתך עליך לכן בני-ישראל שמעו בקולי</p><p>ישעיהו א16: &quot;רַחֲצוּ הִזַּכּוּ הָסִירוּ רֹעַ מַעַלְלֵיכֶם מִנֶּגֶד עֵינָי חִדְלוּ הָרֵעַ&quot;</p><p>ואז כאשר הנכם זכים וטהורים קראו לאלהים בהיותו קרוב</p><p>ישעיהו נה6: &quot;דִּרְשׁוּ יהוה בְּהִמָּצְאוֹ קְרָאֻהוּ בִּהְיוֹתוֹ קָרוֹב&quot;</p><p>-----------------------------------------------------------------</p><p>תהלים כה9: &quot;יַדְרֵךְ עֲנָוִים בַּמִּשְׁפָּט וִילַמֵּד עֲנָוִים דַּרְכּוֹ&quot;</p><p>אני דיין מדריך עֲנָוִים בַּמִּשְׁפָּט   ומלַמֵּד עֲנָוִים דַּרְכּי</p><p>אם אתם ענוים יראי-אלהים בואו לשמוע תורת-משה-דַיָּן</p><p>מאתי מורה לתורה משה דַיָּן </p><p>https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם  מְשָׁרֵת יהוה          </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-19 03:12:52'
		)
		;

