		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/ljon_jorj_nzr1_0.html',
		'<p>https://tora.quest/tnk1/daian</p><p>דַיָּן שֵׁם מְשָׁרֵת יהוה</p><p>בית ספר לנזירים ונביאים</p><p>תהלים יא7: &quot;כִּי צַדִּיק יהוה צְדָקוֹת אָהֵב יָשָׁר יֶחֱזוּ פָנֵימוֹ&quot;</p><p>תהלים יא7: &quot;כִּי צַדִּיק יהוה צְדָקוֹת אָהֵב יָשָׁר??? -אז- יֶחֱזוּ פָנֵימוֹ&quot;</p><p>אם אתה צדיק שעושה צדקות בישרת-לבב --- אז תחזה פני אלהים</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-20 02:18:08'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/ljon_jorj_nzr1_0.html',
		'<p>https://tora.quest/tnk1/daian</p><p>דַיָּן שֵׁם מְשָׁרֵת יהוה</p><p>בית ספר לנזירים ונביאים</p><p>תהלים יא7: &quot;כִּי צַדִּיק יהוה צְדָקוֹת אָהֵב יָשָׁר יֶחֱזוּ פָנֵימוֹ&quot;</p><p>תהלים יא7: &quot;כִּי צַדִּיק יהוה צְדָקוֹת אָהֵב יָשָׁר??? -אז- יֶחֱזוּ פָנֵימוֹ&quot;</p><p>אם אתה צדיק שעושה צדקות בישרת-לבב --- אז תחזה פני אלהים</p><p>פרוש לבאר</p><p>תהלים יא, ז מלמד שהקרבה לאלוהים אינה תוצאה של מעמד חברתי, תואר רבני או שנות לימוד בישיבה. </p><p>“צדיק יהוה צדקות אהב” — יהוה אוהב מעשי צדק, יושר, לב נקי. “ישר יחזו פנימו” — מי שחי ביושר אמיתי, מי שמקיים צדקה ומשפט בלב שלם, הוא זה שזוכה לחזות פני יהוה. </p><p>לא הלימוד לבדו הוא שמקרב את האדם אל האל, אלא טוהר הלב והמעשה. כל אדם — רב, תלמיד, גר, פשוטי עם — יכול להיות קרוב אל יהוה אם הוא חי ביושר ובצדקה. </p><p>זהו תנאי רוחני אוניברסלי, לא מעמדי.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-20 02:58:05'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

