		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2690_3.html',
		'<p>קהלת ו7: &quot;כָּל עֲמַל הָאָדָם לְפִיהוּ וְגַם הַנֶּפֶשׁ לֹא תִמָּלֵא&quot;</p><p>תהלים ח6: &quot;וַתְּחַסְּרֵהוּ מְּעַט מֵאֱלֹהִים וְכָבוֹד וְהָדָר תְּעַטְּרֵהוּ&quot;</p><p> וְגַם הַנֶּפֶשׁ לֹא תִמָּלֵא = וַתְּחַסְּרֵהוּ מְּעַט מֵאֱלֹהִים</p><p>זה נכון על האדם אבל איש אלהים נפשו מלאה ולא חסרה</p><p> &quot;יהוה אֱלֹהֶיךָ עִמָּךְ לֹא חָסַרְתָּ דָּבָר&quot; = על כן נביא שמח חכם-לב נבון</p><p>דברים ב7: &quot;כִּי יהוה אֱלֹהֶיךָ בֵּרַכְךָ בְּכֹל מַעֲשֵׂה יָדֶךָ יָדַע לֶכְתְּךָ אֶת הַמִּדְבָּר הַגָּדֹל הַזֶּה זֶה אַרְבָּעִים שָׁנָה יהוה אֱלֹהֶיךָ עִמָּךְ לֹא חָסַרְתָּ דָּבָר&quot; </p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-20 04:12:26'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0109_2.html',
		'<p>הערבים הפלשתינים הם צאצאי הכנענים אשר אלהים ציוה את בני ישראל בימי יהושע בן-נון להשמידם</p><p>הערבים הפלשתינים צאצאי כנען הם עם של רוצחים והומוסקסואלים לכן ציוה אלהים להשמידם</p><p>כידוע כנען הוא זה שאשם בחטא אביו חם שפשע במשכב סדום בין זכרים ועוד עם נֹחַ אבי כל האנושות</p><p>(כד) וַיִּיקֶץ נֹחַ מִיֵּינוֹ וַיֵּדַע אֵת אֲשֶׁר עָשָׂה לוֹ בְּנוֹ הַקָּטָן:</p><p>(כה) וַיֹּאמֶר אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו:</p><p>לכן הערבים הפלשתינים צאצאי כנען ההומוסקסואל מתחברים עם הלהטבי&quot;ם של מפלגת הדמוקרטים אויבי ישראל</p><p>הכל מתחבר הכל מובן ההיסטוריה חוזרת על עצמה</p><p>-</p><p>הערה: אני לא קורא לפגוע בכנענים אלא להשמיד את תרבות החטאים שלהם שנמצאת לדאבוני גם בישראלים רבים</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-20 10:01:32'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

