		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0146_2.html',
		'<p>מאת דיין עבד-יהוה וּמְשִׁיחו</p><p>הַמִּקְרָא מַצִּיב שְׁלֹשָׁה תְּחֻמִים עֶלְיוֹנִים:</p><p>נְבוּאָה, חָכְמָה וְדַעַת־אֱלֹהִים.</p><p>לְכָל אֶחָד מֵהֶם יֵשׁ דְּמוּת־פִּסְגָּה שֶׁאֵין לְמַעְלָה מִמֶּנָּה.</p><p>הַמָּשִׁיחַ הָעָתִיד — כְּפִי הַכְּתוּב — אֵינוֹ עוֹלֶה עַל מֹשֶׁה בַּנְּבוּאָה, וְאֵינוֹ עוֹלֶה עַל שְׁלֹמֹה בַּחָכְמָה.</p><p>אֲבָל הוּא נוֹשֵׂא מַדְרֵגָה שְׁלִישִׁית שֶׁאֵינָהּ מֵהֶן — דַּעַת־אֱלֹהִים.</p><p>הַמָּשִׁיחַ יֵשְׁנוֹ, נִמְצָא וְעוֹמֵד בְּתוֹךְ הָעוֹלָם;</p><p>אֲבָל אֵינוֹ גָּדוֹל בַּנְּבוּאָה מִמֹּשֶׁה וְאֵינוֹ גָּדוֹל בַּחָכְמָה מִשְּׁלֹמֹה — כִּי הַכְּתוּב עַצְמוֹ קוֹבֵעַ אֶת הַגְּבוּל.</p><p>גְּדוּלָּתוֹ בְּמַדְרֵגָה אַחֶרֶת: דַּעַת־אֱלֹהִים.</p><p>מֹשֶׁה — פִּסְגַּת הַנְּבוּאָה</p><p>הַכְּתוּב אוֹמֵר בְּפֵרוּשׁ:</p><p>וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה אֲשֶׁר יְדָעוֹ יְהוָה פָּנִים אֶל־פָּנִים  (דְּבָרִים ל״ד 10)</p><p>פֵּרוּשׁ הַדָּבָר: מֹשֶׁה הוּא פִּסְגַּת הַנְּבוּאָה הָאֱנוֹשִׁית. אֵין נָבִיא שֶׁהָיָה אוֹ שֶׁיִּהְיֶה גָּדוֹל מִמֶּנּוּ.</p><p>הַמָּשִׁיחַ יֵשְׁנוֹ, אֲבָל אֵינוֹ גָּדוֹל בַּנְּבוּאָה מִמֹּשֶׁה — כִּי הַתּוֹרָה עַצְמָהּ קוֹבַעַת כָּךְ.</p><p>לָכֵן: מֹשֶׁה הוּא רַבּוֹ וּמוֹרוֹ שֶׁל הַמָּשִׁיחַ בְּתְּחוּם הַנְּבוּאָה.</p><p>שְׁלֹמֹה — פִּסְגַּת הַחָכְמָה</p><p>הַכְּתוּב אוֹמֵר: הִנֵּה עָשִׂיתִי כִּדְבָרֶיךָ; הִנֵּה נָתַתִּי לְךָ לֵב חָכָם וְנָבוֹן, אֲשֶׁר כָּמוֹךָ לֹא הָיָה לְפָנֶיךָ, וְאַחֲרֶיךָ לֹא יָקוּם כָּמוֹךָ  (מְלָכִים א׳ ג 12)</p><p>פֵּרוּשׁ הַדָּבָר: שְׁלֹמֹה הוּא פִּסְגַּת הַחָכְמָה הָאֱנוֹשִׁית. -- אֵין אָדָם שֶׁהָיָה אוֹ שֶׁיִּהְיֶה חָכָם מִמֶּנּוּ.</p><p>הַמָּשִׁיחַ יֵשְׁנוֹ, אֲבָל אֵינוֹ גָּדוֹל בַּחָכְמָה מִשְּׁלֹמֹה — כִּי הַכְּתוּב עַצְמוֹ שׁוֹלֵל אֶת זֶה.</p><p>לָכֵן: שְׁלֹמֹה הוּא רַבּוֹ וּמוֹרוֹ שֶׁל הַמָּשִׁיחַ בְּתְּחוּם הַחָכְמָה.</p><p>הַמָּשִׁיחַ — פִּסְגַּת דַּעַת־אֱלֹהִים</p><p>כָּאן בָּאָה הַנְּקֻדָּה הָעִקָּרִית:</p><p>הַמָּשִׁיחַ אֵינוֹ גָּדוֹל בַּנְּבוּאָה מִמֹּשֶׁה, וְאֵינוֹ גָּדוֹל בַּחָכְמָה מִשְּׁלֹמֹה — אֲבָל הוּא גָּדוֹל מִכֻּלָּם בְּדַעַת־אֱלֹהִים.</p><p>דַּעַת־אֱלֹהִים זוֹ מַדְרֵגָה אַחֶרֶת לְגַמְרֵי:</p><p>קֶשֶׁר, קִרְבָה, יְדִיעָה פְּנִימִית, הַכָּרָה יְשִׁירָה, הִתְאַחֲדוּת רְצוֹנִית עִם רְצוֹן יהוה.</p><p>הַכְּתוּב מַצְבִּיעַ עַל זֶה: כִּי כֻּלָּם יֵדְעוּ אוֹתִי  (יִרְמְיָהוּ ל״א 33)</p><p>וְנָחָה עָלָיו רוּחַ יְהוָה… רוּחַ דַּעַת וְיִרְאַת יְהוָה  (יְשַׁעְיָהוּ י״א 2)</p><p>דַּעַת־אֱלֹהִים הִיא מַדְרֵגָה שֶׁל קֶשֶׁר יָשִׁיר — לֹא שֶׁל חָזוֹן וְלֹא שֶׁל מֵידָע אֱנוֹשִׁי.</p><p>לָכֵן: הַמָּשִׁיחַ יֵשְׁנוֹ, וְהוּא גָּדוֹל מִכֻּלָּם בְּדַעַת־אֱלֹהִים, כִּי זֶה תְּחוּם אַחֵר </p><p>סִכּוּם הַדְּבָרִים</p><p>מֹשֶׁה — פִּסְגַּת הַנְּבוּאָה.</p><p>שְׁלֹמֹה — פִּסְגַּת הַחָכְמָה.</p><p>הַמָּשִׁיחַ — פִּסְגַּת דַּעַת־אֱלֹהִים.</p><p>הַמָּשִׁיחַ אֵינוֹ מַחֲלִיף אֶת מֹשֶׁה אוֹ אֶת שְׁלֹמֹה בְּתְּחוּמָם אֶלָּא מַמְשִׁיךְ אוֹתָם:</p><p>מֹשֶׁה — רַבּוֹ בַּנְּבוּאָה.</p><p>שְׁלֹמֹה — רַבּוֹ בַּחָכְמָה.</p><p>וְהַמָּשִׁיחַ — נוֹשֵׂא מַדְרֵגָה שְׁלִישִׁית, עֶלְיוֹנָה מִכֻּלָּן — דַּעַת־אֱלֹהִים, שֶׁאֵינָהּ מֵידָע וְאֵינָהּ חָזוֹן, אֶלָּא קֶשֶׁר רגשי יָשִׁיר עִם יהוה.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-20 16:16:12'
		)
		;

SET character_set_client=utf8mb3;
