		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0146_2.html',
		'<p> מאת דיין עבד־יהוה וּמְשִׁיחו</p><p>הַמִּקְרָא מַצִּיב שְׁלֹשָׁה תְּחֻמִים עֶלְיוֹנִים:</p><p>נְבוּאָה, חָכְמָה דַּעַת־אֱלֹהִים.  </p><p>לְכָל תְּחוּם יֵשׁ פִּסְגָּה שֶׁאֵין לְמַעְלָה מִמֶּנָּה.</p><p>מֹשֶׁה — פִּסְגַּת הַנְּבוּאָה</p><p>וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה אֲשֶׁר יְדָעוֹ יְהוָה פָּנִים אֶל־פָּנִים  (דברים ל״ד 10)</p><p>הַמָּשִׁיחַ יֵשְׁנוֹ, אֲבָל אֵינוֹ גָּדוֹל בַּנְּבוּאָה מִמֹּשֶׁה. אדרבא כי משה הוא מורו ורבו</p><p>-</p><p>שְׁלֹמֹה — פִּסְגַּת הַחָכְמָה והתבונה</p><p>הִנֵּה נָתַתִּי לְךָ לֵב חָכָם וְנָבוֹן אֲשֶׁר כָּמוֹךָ לֹא הָיָה לְפָנֶיךָ וְאַחֲרֶיךָ לֹא יָקוּם כָּמוֹךָ  (מלכים א׳ ג 12)</p><p>הַמָּשִׁיחַ יֵשְׁנוֹ, אֲבָל אֵינוֹ גָּדוֹל בַּחָכְמָה מִשְּׁלֹמֹה. אדרבא כי שלמה הוא מורו ורבו</p><p>הַמָּשִׁיחַ — פִּסְגַּת דַּעַת־אֱלֹהִים</p><p>דַּעַת־אֱלֹהִים הִיא רֶגֶשׁ יָשִׁיר, קֶשֶׁר פְּנִימִי וּמַגָּע לב רוּחָנִי עִם יהוה. לֹא בהכרח חָזוֹן לֹא בהכרח מֵידָע — אֶלָּא קִרְבָה עד כדי חיבור מלא.</p><p>ישעיהו יא2: &quot;וְנָחָה עָלָיו רוּחַ יהוה רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יהוה&quot;</p><p>בְּדַעַת־אֱלֹהִים — הַמָּשִׁיחַ גָּדוֹל מִכֻּלָּם.</p><p>סוף דבר</p><p>מֹשֶׁה — רֹאשׁ ולב הַנְּבוּאָה.</p><p>שְׁלֹמֹה — רֹאשׁ ולב הַחָכְמָה.</p><p>הַמָּשִׁיחַ — רֹאשׁ ולב דַּעַת־אֱלֹהִים.</p><p>הַמָּשִׁיחַ וּבְקֶשֶׁר הרגשי הַיָּשִׁיר עִם יהוה הוּא עוֹלֶה עַל כֻּלָּם.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-20 16:34:29'
		)
		;

SET character_set_client=utf8mb3;
