		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1502_1.html',
		'<p>תהלים יב7: &quot;אִמֲרוֹת יהוה אֲמָרוֹת טְהֹרוֹת כֶּסֶף צָרוּף בַּעֲלִיל לָאָרֶץ מְזֻקָּק שִׁבְעָתָיִם&quot;</p><p>תהלים יב8: &quot;אַתָּה יהוה תִּשְׁמְרֵם תִּצְּרֶנּוּ מִן הַדּוֹר זוּ לְעוֹלָם&quot;</p><p>תהלים יב9: &quot;סָבִיב רְשָׁעִים יִתְהַלָּכוּן כְּרֻם זֻלּוּת לִבְנֵי אָדָם&quot;</p><p>יש הבדל בין מי שנאמן לדבר יהוה — לבין מי שמתהלך סביבו בלבד</p><p>דברי יהוה טהורים ומזוקקים, אך הרשעים מקיפים אותם מבחוץ.</p><p>יש אנשים הקרובים לתורה במעשה או בדיבור, אך אינם הולכים בה באמת.</p><p>לכן האנשים האלה מתוסכלים כי מרגישים פספוס והחמצה בחיים וחסר להם</p><p>זה עונשם של הרשעים אשר אינם שומעים בקול יהוה ובקול דיין עבדו משיחו</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-21 01:34:17'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1502_1.html',
		'<p>תהלים יב7: &quot;אִמֲרוֹת יהוה אֲמָרוֹת טְהֹרוֹת כֶּסֶף צָרוּף בַּעֲלִיל לָאָרֶץ מְזֻקָּק שִׁבְעָתָיִם&quot;</p><p>תהלים יב8: &quot;אַתָּה יהוה תִּשְׁמְרֵם תִּצְּרֶנּוּ מִן הַדּוֹר זוּ לְעוֹלָם&quot;</p><p>תהלים יב9: &quot;סָבִיב רְשָׁעִים יִתְהַלָּכוּן כְּרֻם זֻלּוּת לִבְנֵי אָדָם&quot;</p><p>יש הבדל בין מי שנאמן לדבר יהוה — לבין מי שמתהלך סביבו בלבד</p><p>דברי יהוה טהורים ומזוקקים, אך הרשעים מקיפים אותם מבחוץ.</p><p>יש אנשים אשר שוגים באמרי-דעת, אך אינם מקיימים ללכת בתורה באמת.</p><p>משלי יט27: &quot;חַדַל בְּנִי לִשְׁמֹעַ מוּסָר לִשְׁגוֹת מֵאִמְרֵי דָעַת&quot; </p><p>לכן האנשים האלה מתוסכלים כי מרגישים פספוס והחמצה בחיים וחסר להם</p><p>זה עונשם של הרשעים אשר אינם שומעים בקול יהוה ובקול דיין עבדו משיחו</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-21 01:44:48'
		)
		;

