		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0223_0.html',
		'<p>את עץ הדעת מייצגים כל בעלי החיים שאינם כשרים למאכל והאדם ביניהם עם כל החיות שאינן טהורות למאכל</p><p>ועץ החיים מיוצג על ידי החיות הטהורות למאכל שמותר לגעת בהן ולאכול מהן וזאת בתנאי שאתה טהור</p><p>עתה בני ישראל אל תאכלו מהחיות אשר אינן טהורות אלה מעץ-הדעת אלא חנון אותן כי בחוננך אותן חננת הדעת</p><p>על כן מי שחונן את בעלי החיים עושה עמם חסד נותן להם לאכול ולהתרבות זה נקרא חוֹנֵן הַדָּעַת</p><p>אַתָּה חוֹנֵן לְאָדָם דַּעַת וּמְלַמֵּד לֶאֱנוֹשׁ בִּינָה וְחָנֵּנוּ מֵאִתְּךָ חָכְמָה בִּינָה וָדָעַת. בָּרוּךְ אַתָּה יהוה חוֹנֵן הַדָּעַת.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-21 03:57:47'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

