		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2738_3.html',
		'<p>משלי כד5: &quot;גֶּבֶר חָכָם בַּעוֹז וְאִישׁ דַּעַת מְאַמֶּץ כֹּחַ&quot; </p><p>דיין הוא איש דעת אלהים על כן מצוה לשמוע בקולו</p><p>ואשר לא ישמעו בקול דיין איש הדעת כי לא יבינו דעת </p><p>לכן לסוררים לחסרי הבינה האלה יקרא רשעים כי...</p><p>משלי כט7: &quot;יֹדֵעַ צַדִּיק דִּין דַּלִּים רָשָׁע לֹא יָבִין דָּעַת&quot; </p><p>את עץ הדעת מייצגים כל בעלי החיים שאינם כשרים למאכל והאדם ביניהם עם כל החיות שאינן טהורות למאכל</p><p>ועץ החיים מיוצג על ידי החיות הטהורות למאכל שמותר לגעת בהן ולאכול מהן וזאת בתנאי שאתה טהור</p><p>עתה בני ישראל אל תאכלו מהחיות אשר אינן טהורות אלה מעץ-הדעת אלא חנון אותן כי בחוננך אותן חננת הדעת</p><p>על כן מי שחונן את בעלי החיים עושה עמם חסד נותן להם לאכול ולהתרבות זה נקרא חוֹנֵן הַדָּעַת</p><p>אַתָּה חוֹנֵן לְאָדָם דַּעַת וּמְלַמֵּד לֶאֱנוֹשׁ בִּינָה וְחָנֵּנוּ מֵאִתְּךָ חָכְמָה בִּינָה וָדָעַת. בָּרוּךְ אַתָּה יהוה חוֹנֵן הַדָּעַת.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-21 06:13:52'
		)
		;

SET character_set_client=utf8mb3;
