		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/tora/jmot/jm-1821.html',
		'<p>לאורך שנים אנחנו בוחרים ימין ומקבלים ימין-חלקי ולא באמת ימין מלא מלא כמו שאומרים</p><p>ואם יו&quot;ר הכנסת מטעם הליכוד הוא מאנשי סדום אז זה קרוב למפלגת הלהטבים של יאיר גולן </p><p>זה לא באמת ימין --- זה ימין שקר וכמעט אין הבדל בין הימין לשמאל------- לכן שמעו מה דיין דורש</p><p>יש לפנות לאומות המאוחדות [או&quot;ם] להציג את מפת ישראל וגבולה על פי המקרא ולהגיד לאום כי ארץ ישראל היא אדמת קודש לכן רק אנשי קודש יכולים להיות עליה לכן יש לחוקק חק שבכל גבולה של ארץ ישראל ישמר ברית עשרת הדברים ככתוב בתורת משה ואז אין להפלות בין כל איש שיחפוץ לעלות לארץ ישראל אם הוא מצהיר להקים את כל עשרת דברי הברית ומי אשר לא ישמור את ברית עשרת הדברים יגורש מישראל בין אם הוא יהודי או נוצרי או מוסלמי וכל דת אחרת</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-21 09:33:46'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

