		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0146_2.html',
		'<p>מאת דיין עבד־יהוה וּמְשִׁיחו</p><p> ישעיהו יא2: &quot;וְנָחָה עָלָיו רוּחַ יהוה רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יהוה&quot;</p><p>המשיח הוא ברוח יהוה בכל ששת תכונות אלהים --- אך בחכמה ותבונה שלמה גדול יותר ובנבואה שהיא יראת-אלהים משה גדול יותר</p><p>מֹשֶׁה — רֹאשׁ ולב הַנְּבוּאָה.---------- דברים לד10: &quot;וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה אֲשֶׁר יְדָעוֹ יהוה פָּנִים אֶל פָּנִים&quot;</p><p>שְׁלֹמֹה — רֹאשׁ ולב הַחָכְמָה. ------- מלכים א ג12: &quot;הִנֵּה עָשִׂיתִי כִּדְבָרֶיךָ הִנֵּה נָתַתִּי לְךָ לֵב חָכָם וְנָבוֹן אֲשֶׁר כָּמוֹךָ לֹא הָיָה לְפָנֶיךָ וְאַחֲרֶיךָ לֹא יָקוּם כָּמוֹךָ&quot;</p><p>הַמָּשִׁיחַ — רֹאשׁ ולב דַּעַת־אֱלֹהִים. --- וּבְקֶשֶׁר הרגשי הַיָּשִׁיר עִם יהוה הוּא עוֹלֶה עַל כֻּלָּם בדעת-יהוה.</p><p>-</p><p>על כן דיין שם משרת-יהוה ומשיחו הוא הגואל כי הוא חונן הדעת אשר זה כלי הגאולה מאת יהוה</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-21 13:38:23'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

