		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2655_5.html',
		'<p>משלי כב9: &quot;טוֹב עַיִן הוּא יְבֹרָךְ כִּי נָתַן מִלַּחְמוֹ לַדָּל&quot;</p><p>משלי כב9: &quot;טוֹב עַיִן הוּא יְבֹרָךְ = יְבֹרָכו כל בעלי-החיים והילדים הטהורים כִּי להם עיניים טובות&quot;</p><p>כי כל אלה לא חטאו לאכול מפרי-עץ-הדעת על-כן טהורי-עיניים הם וראויים לעדן גן-יהוה-אלהים</p>',
		'115934331744503251746',
		'DAIAN SHEM',
