		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0526_3.html',
		'<p>מאת </p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה          </p><p> https://tora.quest/tnk1/daian</p><p>                     </p><p>הקשר בין כהן-יהוה לבין הילד הפנימי</p><p>משלי כב9: &quot;טוֹב עַיִן הוּא יְבֹרָךְ ....... כִּי נָתַן מִלַּחְמוֹ לַדָּל&quot;</p><p>משלי כב9: &quot;טוֹב עַיִן הוּא יְבֹרָךְ = יְבֹרָכו כל בעלי-החיים והילדים הטהורים כִּי להם עיניים טובות&quot;</p><p>כי כל אלה לא חטאו לאכול מפרי-עץ-הדעת על-כן טהורי-עיניים הם וראויים לעדן גן-יהוה-אלהים</p><p>-</p><p>בעת &quot;שמירת הברית&quot; אתה לא מוציא זרעך מתוכך וככה אתה שומר על הילד הפנימי שבך</p><p>הילד הטהור הזה שבך יחכה בתוכך עד יכנס לרחם הטהור של אשה בתולה בחופה וקידושין</p><p>על כן כתוב לכהן יהוה</p><p>ויקרא כא14: &quot;אַלְמָנָה וּגְרוּשָׁה וַחֲלָלָה זֹנָה אֶת אֵלֶּה לֹא יִקָּח כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-22 04:47:55'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2655_5.html',
		'<p>תהלים לז26: &quot;כָּל הַיּוֹם חוֹנֵן וּמַלְוֶה וְזַרְעוֹ לִבְרָכָה&quot;.......</p><p>משלי כב9: &quot;טוֹב עַיִן הוּא יְבֹרָךְ ....... כִּי נָתַן מִלַּחְמוֹ לַדָּל&quot;</p><p>משלי כב9: &quot;טוֹב עַיִן הוּא יְבֹרָךְ = יְבֹרָכו כל בעלי-החיים והילדים הטהורים כִּי להם עיניים טובות&quot;</p><p>כי כל אלה לא חטאו לאכול מפרי-עץ-הדעת על-כן טהורי-עיניים הם וראויים לעדן גן-יהוה-אלהים</p><p>-</p><p>בעת &quot;שמירת הברית&quot; אתה לא מוציא זרעך מתוכך וככה אתה שומר על הילד הפנימי שבך</p><p>הילד הטהור הזה שבך יחכה בתוכך עד יכנס לרחם הטהור של אשה בתולה בחופה וקידושין</p><p>על כן כתוב לכהן יהוה</p><p>ויקרא כא14: &quot;אַלְמָנָה וּגְרוּשָׁה וַחֲלָלָה זֹנָה אֶת אֵלֶּה לֹא יִקָּח כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-22 06:15:53'
		)
		;

