		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0529_3.html',
		'<p>במדבר יג17: &quot;וַיִּשְׁלַח אֹתָם מֹשֶׁה לָתוּר אֶת אֶרֶץ כְּנָעַן וַיֹּאמֶר אֲלֵהֶם עֲלוּ זֶה בַּנֶּגֶב....... וַעֲלִיתֶם אֶת הָהָר&quot;</p><p>יהושע טו19: &quot;וַתֹּאמֶר תְּנָה לִּי בְרָכָה כִּי אֶרֶץ הַנֶּגֶב....... נְתַתָּנִי וְנָתַתָּה לִי גֻּלֹּת מָיִם וַיִּתֶּן לָהּ אֵת גֻּלֹּת עִלִּיּוֹת וְאֵת גֻּלֹּת תַּחְתִּיּוֹת&quot;</p><p>שופטים א15: &quot;וַתֹּאמֶר לוֹ הָבָה לִּי בְרָכָה כִּי אֶרֶץ הַנֶּגֶב....... נְתַתָּנִי וְנָתַתָּה לִי גֻּלֹּת מָיִם וַיִּתֶּן לָהּ כָּלֵב אֵת גֻּלֹּת עִלִּית וְאֵת גֻּלֹּת תַּחְתִּית&quot;</p><p>מצד אחד אוהב את הקדושה שבנגב</p><p>מצד שני אני איש רגיש מאד ואוהב מים</p><p>על כן הפתרון בשבילי הוא מקום מקוה מים בארץ הנגב בנחלת יהודה</p><p>אני מחכה ליום הַהוּא</p><p>יואל ד18: &quot;וְהָיָה בַיּוֹם הַהוּא יִטְּפוּ הֶהָרִים עָסִיס וְהַגְּבָעוֹת תֵּלַכְנָה חָלָב וְכָל אֲפִיקֵי יְהוּדָה יֵלְכוּ מָיִם וּמַעְיָן מִבֵּית יהוה יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִּׁטִּים&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-22 07:21:32'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/ktuv/mj/20-21.html',
		'<p>1.משלי כ21: &quot;נַחֲלָה מבחלת[מְבֹהֶלֶת] בָּרִאשֹׁנָה וְאַחֲרִיתָהּ לֹא תְבֹרָךְ&quot; </p><p> אז איך...לכאורה סתירה </p><p>2.קהלת ז8: &quot;טוֹב אַחֲרִית דָּבָר מֵרֵאשִׁיתוֹ טוֹב אֶרֶךְ רוּחַ מִגְּבַהּ רוּחַ&quot;  </p><p>-</p><p>עתה אבאר לכם על פי הפסוק הבא</p><p>תהלים מח6: &quot;הֵמָּה רָאוּ כֵּן תָּמָהוּ נִבְהֲלוּ = נֶחְפָּזוּ&quot;</p><p>1.חיפזון הוא תוצאה של בהלה ולכן לא יצא מזה דבר טוב של ברכה</p><p>לעומת זאת</p><p>2. טוֹב אַחֲרִית דָּבָר מֵרֵאשִׁיתוֹ = [תחילה] קשה באימונים [ואחרי כן] קל בקרב</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-22 13:44:17'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2821_2.html',
		'<p>מאת דיין שם עבד-יהוה ומשיחו</p><p>תהלים נו9-10: &quot;נֹדִי סָפַרְתָּה אָתָּה שִׂימָה דִמְעָתִי בְנֹאדֶךָ הֲלֹא בְּסִפְרָתֶךָ אָז יָשׁוּבוּ אוֹיְבַי אָחוֹר בְּיוֹם אֶקְרָא זֶה יָדַעְתִּי כִּי אֱלֹהִים לִי&quot;</p><p>יש לללמד את בני ישראל לקרוא בדמעה לאלהים במיוחד את המגזר של החרדים שיכולים להיות לוחמים מבלי להתגייס לצה&quot;ל</p><p>כאשר צדיק בוכה בדמעות בעת קוראו לאלהי ישראל אז יהוה אלהים צבאות שומע ומשיב אחור את כל אויבי ישראל </p><p>אם יבינו זאת במשרד הבטחון אז הנשק הזה שהיה כבר של משיח-יהוה עוד מימי קדם הוא גם הנשק העתידי בעידן הגרעיני</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה        </p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-22 17:47:35'
		)
