		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0518_2.html',
		'<p>ההבדל בין דורש אלהים לבין דורש את המתים אשר הוא כנבלה גם הוא נחשב כמת לא חי</p><p>תהלים יד1: &quot;לַמְנַצֵּחַ לְדָוִד אָמַר נָבָל בְּלִבּוֹ אֵין אֱלֹהִים הִשְׁחִיתוּ הִתְעִיבוּ עֲלִילָה אֵין עֹשֵׂה טוֹב&quot;</p><p>תהלים יד2: יהוה מִשָּׁמַיִם הִשְׁקִיף עַל בְּנֵי אָדָם לִרְאוֹת הֲיֵשׁ מַשְׂכִּיל דֹּרֵשׁ אֶת אֱלֹהִים&quot;</p><p>תהלים נג1: &quot;לַמְנַצֵּחַ עַל מָחֲלַת מַשְׂכִּיל לְדָוִד&quot;</p><p>תהלים נג2: &quot;אָמַר נָבָל בְּלִבּוֹ אֵין אֱלֹהִים הִשְׁחִיתוּ וְהִתְעִיבוּ עָוֶל אֵין עֹשֵׂה טוֹב&quot;</p><p>תהלים נג3: &quot;אֱלֹהִים מִשָּׁמַיִם הִשְׁקִיף עַל בְּנֵי אָדָם לִרְאוֹת הֲיֵשׁ מַשְׂכִּיל דֹּרֵשׁ אֶת אֱלֹהִים&quot;</p><p>הנבל הוא כמת אשר ההיפך מדורש אלהים אשר הוא חי --- וּבָחַרְתָּ בַּחַיִּים</p><p>דברים ל19: &quot;העדתי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ הַחַיִּים וְהַמָּוֶת נָתַתִּי לְפָנֶיךָ הַבְּרָכָה וְהַקְּלָלָה וּבָחַרְתָּ בַּחַיִּים....... לְמַעַן תִּחְיֶה אַתָּה וְזַרְעֶךָ&quot; </p><p> עמוס ה4: &quot;כִּי כֹה אָמַר יהוה לְבֵית יִשְׂרָאֵל דִּרְשׁוּנִי וִחְיוּ&quot;</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה          </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-23 02:43:40'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

