		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0146_2.html',
		'<p>מאת דיין שם   ------- עבד-יהוה ומשיחו</p><p>בפסוקי התנ״ך מופיע שוב ושוב המתח שבין כוח לבין תיקון, בין גבורה לבין ענוה. כאשר הכוח הרוחני או המעמד הציבורי של אדם עולים על מידת הענוה שלו, נוצר פגם פנימי המתבטא לעיתים בצרעת — מחלה רוחנית־מוסרית המופיעה במקרא כסימן לאי־איזון נפשי ומוסרי. רעיון זה מתגלה בעוצמה מיוחדת בסיפורו של נעמן שר צבא ארם.</p><p>במלכים ב ה1 נאמר: “וְנַעֲמָן שַׂר צְבָא מֶלֶךְ אֲרָם הָיָה אִישׁ גָּדוֹל לִפְנֵי אֲדֹנָיו וּנְשֻׂא פָנִים כִּי בּוֹ נָתַן יהוה תְּשׁוּעָה לַאֲרָם וְהָאִישׁ הָיָה גִּבּוֹר חַיִל מְצֹרָע.”  </p><p>הכתוב מציב בכוונה שתי תכונות זו לצד זו: “גיבור חיל” ו“מצורע”. זהו פרדוקס מוסרי: אדם בעל כוח עצום, מעמד, הצלחה וגבורה — ובו בזמן נושא פגם עמוק. הצרעת אינה תוצאה של חולשה, אלא של עודף כוח שאינו מאוזן בענוה. כאשר הגבורה מתרוממת מעל הענוה, נוצר מתח פנימי שהגוף הרוחני אינו יכול להכיל, והפגם מתגלה.</p><p>כדי להבין זאת, ניתן לדמיין שני עמודים — עמוד הגבורה ועמוד הענוה. כל עוד עמוד הענוה גבוה מעמוד הגבורה, האדם נמצא באיזון בריא: כוחו מזוכך, פעולותיו מדויקות, וליבו נקי מגאווה. אך כאשר עמוד הגבורה מתרומם מעל עמוד הענוה, נוצר מצב של גאווה: “כוחי ועוצם ידי עשה לי את החיל הזה.” במצב כזה של עודף גבורה שאינה מאוזנת בענוה — מופיעה הצרעת. זהו ביטוי חיצוני לפגם פנימי.</p><p>לכן כתוב על נעמן: “וְהָאִישׁ הָיָה גִּבּוֹר חַיִל מְצֹרָע.”  </p><p>הצרעת אינה סתירה לגבורה שלו — היא תוצאה של גבורה שאינה מאוזנת. אם נעמן לא היה כה גיבור, לא היה מגיע למצב שבו עמוד הגבורה עולה על עמוד הענוה, ולכן ייתכן שלא היה בו נגע הצרעת. ככל שהאדם גדול יותר, כך האיזון הנדרש גדול יותר; וכאשר האיזון נשבר — הפגם מתגלה.</p><p>מכאן גם נובעת אזהרה מוסרית: אל לנו לשפוט את נעמן בקלות. הוא לא היה “אדם פשוט”, אלא מפקד וגנרל גדול, אדם שנשא על כתפיו אחריות עצומה. חז״ל אמרו: “אל תשפוט אדם עד שתגיע למקומו.”  </p><p>הגבורה הגדולה שלו יצרה מתח פנימי גדול — וכאשר הענוה לא הייתה מספיקה לאזן את הכוח, הופיעה הצרעת.</p><p>המסר העמוק הוא זה: גבורה אמיתית חייבת להיות משולבת בענוה. כוח ללא ענוה הופך לגאווה; גאווה הופכת לפגם; והפגם מתגלה בצרעת. זהו חוק רוחני החוזר בכל התנ״ך — מן מרים, דרך עוזיהו, ועד נעמן.</p><p>האיזון בין גבורה לענוה הוא יסוד הבריאות הרוחנית של האדם.</p><p>אלישע הנביא ברוח חכמת אלהים בקרבו שלח את נעמן לרחוץ 7 פעמים בנהר הירדן כדי לקבל את המסר של רוח אלהים המרחפת על פני המים</p><p>כי רוח אלהים היא המאזנת במדוייק בין כל התכונות של יהוה ככתוב על משיח יהוה בספר הנביא</p><p>ישעיהו יא2: &quot;וְנָחָה עָלָיו רוּחַ יהוה רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יהוה&quot;</p><p>האיזון המדוייק בין ששת-תכונות-יהוה הוא הסוד לחיי נצח</p><p>ואף כי שלמה היה חכם מכל האדם הלא חכמתו הייתה גבוהה מאד ובחוסר איזון משאר תכונות האלהים</p><p>לכן המשיח העתידי גדול משלמה אף כי שלמה היה חכם יותר</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-23 04:45:46'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

