		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/kma/qjrim1/hdm.html',
		'<p>תהלים קי1: &quot;לְדָוִד מִזְמוֹר נְאֻם יהוה לַאדֹנִי שֵׁב לִימִינִי עַד אָשִׁית אֹיְבֶיךָ הֲדֹם לְרַגְלֶיךָ&quot;.......</p><p>דברים לג3: &quot;אַף חֹבֵב עַמִּים כָּל קְדֹשָׁיו בְּיָדֶךָ וְהֵם תֻּכּוּ לְרַגְלֶךָ....... יִשָּׂא מִדַּבְּרֹתֶיךָ&quot;</p><p>------------------------------ הֲדֹם לְרַגְלֶיךָ = תֻּכּוּ לְרַגְלֶךָ  ------------------------------</p><p>--------------------------------------------------------------------------------------------</p><p> עַד אָשִׁית אֹיְבֶיךָ הֲדֹם לְרַגְלֶיךָ = עד שישתחוו לך כל אֹיְבֶיךָ כי יהפכו לאוהביך</p><p>שמות כד10: &quot;וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו....... כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-23 13:36:01'
		)
		;

