		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/kma/qjrim1/hdm.html',
		'<p>תהלים קי1: &quot;לְדָוִד מִזְמוֹר נְאֻם יהוה לַאדֹנִי שֵׁב לִימִינִי עַד אָשִׁית אֹיְבֶיךָ הֲדֹם לְרַגְלֶיךָ&quot;.......</p><p>דברים לג3: &quot;אַף חֹבֵב עַמִּים כָּל קְדֹשָׁיו בְּיָדֶךָ וְהֵם תֻּכּוּ לְרַגְלֶךָ....... יִשָּׂא מִדַּבְּרֹתֶיךָ&quot;</p><p>------------------------------ הֲדֹם לְרַגְלֶיךָ = תֻּכּוּ לְרַגְלֶךָ ------------------------------</p><p>--------------------------------------------------------------------------------------------</p><p>עַד אָשִׁית אֹיְבֶיךָ הֲדֹם לְרַגְלֶיךָ = עד שישתחוו לך כל אֹיְבֶיךָ כי יהפכו לאוהביך כעמך</p><p>שמות כד10: &quot;וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו....... כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר&quot;</p><p>-</p><p>על כן כתוב</p><p>&quot;לֶהָבָה תְּלַהֵט רְשָׁעִים&quot; כי בסוף גם הרשעים הופכים לאש שלהבת-יה כמשרתי יהוה</p><p>תהלים קד4: &quot;עֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט&quot;</p><p>אש אלהים להשמדת הרשעים אינה אלא לשינוי מהותם! כי הם עוברים טרנספורמציה.</p><p>הם עצמם נהפכים ל“אֵשׁ לֹהֵט”, כמו המלאכים.</p><p>המשיח באש אלהים מביא את כולם להכנעה אל רגלי יהוה</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-23 14:00:01'
		)
		;

