		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/kma/qjrim1/hdm.html',
		'<p>תהלים קי1: &quot;לְדָוִד מִזְמוֹר נְאֻם יהוה לַאדֹנִי שֵׁב לִימִינִי עַד אָשִׁית אֹיְבֶיךָ הֲדֹם לְרַגְלֶיךָ&quot;.......</p><p>דברים לג3: &quot;אַף חֹבֵב עַמִּים כָּל קְדֹשָׁיו בְּיָדֶךָ וְהֵם תֻּכּוּ לְרַגְלֶךָ....... יִשָּׂא מִדַּבְּרֹתֶיךָ&quot;</p><p>------------------------------ הֲדֹם לְרַגְלֶיךָ = תֻּכּוּ לְרַגְלֶךָ ------------------------------</p><p>--------------------------------------------------------------------------------------------</p><p>עַד אָשִׁית אֹיְבֶיךָ הֲדֹם לְרַגְלֶיךָ = עד שישתחוו לך כל אֹיְבֶיךָ כי יהפכו לאוהביך כעמך</p><p>שמות כד10: &quot;וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו....... כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר&quot;</p><p>-</p><p>על כן כתוב</p><p>&quot;לֶהָבָה תְּלַהֵט רְשָׁעִים&quot; כי בסוף גם הרשעים הופכים לאש שלהבת-יה כמשרתי יהוה</p><p>תהלים קד4: &quot;עֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט&quot;</p><p>אש אלהים להשמדת הרשעים אינה אלא לשינוי מהותם! כי הם עוברים טרנספורמציה.</p><p>הם עצמם נהפכים ל“אֵשׁ לֹהֵט”, כמו המלאכים.</p><p>אדם חי אף כי רשע עדיין נושא הגם כי במעט את רוח אלהים לכן רוח אלהים נשארת אך הרשע מושמד כי כל ה&quot;קליפות נשרפו&quot;</p><p>על כן יהוה אמר למשה איש האלהים</p><p>כִּי יָדַעְתִּי אֶת יִצְרוֹ אֲשֶׁר הוּא עֹשֶׂה --- כי הודיעו זאת רוחות המלאכים הקדושים השוכנים עם יהוה כי נשפטו באש כי היו בעבר רשעים</p><p>דברים לא21: &quot;וְהָיָה כִּי תִמְצֶאןָ אֹתוֹ רָעוֹת רַבּוֹת וְצָרוֹת וְעָנְתָה הַשִּׁירָה הַזֹּאת לְפָנָיו לְעֵד כִּי לֹא תִשָּׁכַח מִפִּי זַרְעוֹ</p><p>כִּי יָדַעְתִּי אֶת יִצְרוֹ .........................................אֲשֶׁר הוּא עֹשֶׂה הַיּוֹם בְּטֶרֶם אֲבִיאֶנּוּ אֶל הָאָרֶץ אֲשֶׁר נִשְׁבָּעְתִּי&quot;</p><p>המשיח באש אלהים מצרף את כולם להכנעה אל רגלי יהוה</p><p>משלי יז3: &quot;מַצְרֵף לַכֶּסֶף וְכוּר לַזָּהָב וּבֹחֵן לִבּוֹת יהוה&quot;</p><p>משלי כז21: &quot;מַצְרֵף לַכֶּסֶף וְכוּר לַזָּהָב וְאִישׁ לְפִי מַהֲלָלוֹ&quot;</p><p>מלאכי ג2: &quot;וּמִי מְכַלְכֵּל אֶת יוֹם בּוֹאוֹ וּמִי הָעֹמֵד בְּהֵרָאוֹתוֹ כִּי הוּא כְּאֵשׁ מְצָרֵף....... וּכְבֹרִית מְכַבְּסִים&quot;</p><p>מלאכי ג3: &quot;וְיָשַׁב מְצָרֵף....... וּמְטַהֵר כֶּסֶף וְטִהַר אֶת בְּנֵי לֵוִי וְזִקַּק אֹתָם כַּזָּהָב וְכַכָּסֶף וְהָיוּ ליהוה מַגִּישֵׁי מִנְחָה בִּצְדָקָה&quot;</p><p>----------------------------------------------------------------------------------------------------------------------------------------</p><p>עתה פרוש לבאר בשפה עממית בשפת העם</p><p>בפסוקי המקרא מתגלה מהלך עמוק ועקבי: אש יהוה איננה משמידה את האדם, אלא משמידה את הרשעה שבו. </p><p>האדם עצמו — הנושא תמיד את רוח אלהים, גם אם במעט — נותר חי, מזוכך, ומתעלה עד שהוא נהפך ל“משרתיו אש לוהט”. </p><p>זהו תהליך של טרנספורמציה רוחנית, שבו הרע נשרף והטוב האלוהי שבאדם נותר ומתחזק.</p><p>היסוד הראשון למהלך זה מופיע בתהלים קי: “עד אשית אויביך הדום לרגליך”. ההדום איננו השמדה אלא הכנעה,</p><p> וכאשר משווים זאת לדברים לג: “והם תֻּכּוּ לרגליך”, מתברר שהדום לרגלי יהוה הוא מצב של קירבה וזיכוך — לא של חורבן. </p><p>האויבים נהפכים לאוהבים; הרשעים נהפכים למשרתים; כולם מובאים אל רגלי יהוה מקום של התגלות וטוהר, </p><p>כפי שמתואר בשמות כד: “ותחת רגליו כמעשה לבנת הספיר”.</p><p>מכאן נובע הפסוק: “להבה תלהט רשעים”. הלהבה אינה מכלה את האדם אלא את הרשע שבו. זהו זיכוך, לא השמדה. </p><p>תהלים ק&quot;ד מאשר זאת: “עושה מלאכיו רוחות, משרתיו אש לוהט”. המלאכים עצמם הם אש — לא אש של חורבן אלא אש של שירות. </p><p>לפי המהלך המקראי, גם הרשעים עוברים את אותה אש: </p><p>הרשעה שבהם נשרפת, רוח אלהים שבהם נשארת, והם נהפכים למשרתיו אש לוהט.</p><p>המקרא מדגיש שוב ושוב שההשמדה היא של הרשעה בלבד: “שומר יהוה את כל אוהביו ואת כל הרשעים ישמיד” (תהלים קמה), </p><p>וכן “ודרך רשעים תאבד” (תהלים א). לא האדם מושמד — אלא דרכו הרעה. האדם חי, כי רוח אלהים בו. </p><p>הרשעה מתכלה, כי היא כדימוי השלילי של עשב הנובל מהר; הצדיק יפרח, כי הוא תמר. </p><p>לכן גם בתהלים ב׳: “ובחרונו יבהלמו” — הבהלה מכוונת אל הרשעים (הסיומת “מו”), לא אל רוח אלהים שבאדם.</p><p>מכאן מתבהר גם הפסוק בדברים ל&quot;א: “כי ידעתי את יצרו אשר הוא עושה היום”. </p><p>לפי הקריאה המיסטית, המלאכים — שהיו בעבר רשעים ונזדככו באש יהוה — יודעים את טבעו של האדם, כי הם עצמם עברו את אותו תהליך של זיכוך. הם מודיעים זאת ליהוה, ולכן יהוה יודע את יצר האדם לא מתוך השמדה אלא מתוך הבנה עמוקה של תהליך הזיכוך.</p><p>המשיח, לפי נבואות הזיכוך, בא באש אלהים כדי לצרף את כולם. זהו תהליך אוניברסלי: </p><p>“מצרף לכסף וכור לזהב ובוחן לבות יהוה” (משלי יז), “מצרף לכסף וכור לזהב ואיש לפי מהללו” (משלי כז), </p><p>וכן מלאכי ג: “כי הוא כאש מצרף… וטיהר את בני לוי… וזיקק אותם כזהב וככסף”. </p><p>האש האלוהית מסירה את הסיגים, מטהרת את האדם, ומעמידה אותו כמי שמגיש מנחה בצדקה.</p><p>לכן, כאשר דיין כמלאך־אלהים “חושב עליך רעה”, אין זו רעה ממש. זו פעולת זיכוך — כדי שתדע את אלהים. </p><p>האדם בלי דעת נוהג כרשע, ולכן מצרפים אותו בכור הכסף או הזהב להסיר את הסיגים מעליו.או בלשון המקובלים &quot;קליפות&quot;</p><p> הרעה האלוהית איננה עונש אלא תיקון; איננה השמדה אלא טיהור; איננה חורבן אלא התעלות.</p><p>זהו מהלך מקראי שלם:</p><p>הרשעה מושמדת — האדם נשאר.</p><p>הקליפות נשרפות — רוח אלהים נשארת.</p><p>האדם נזדכך — ונהפך למשרתיו אש לוהט.</p><p>המשיח מצרף את כולם — עד הכנעה לרגלי יהוה.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-23 15:12:24'
		)
		;

