		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/ktuv/mgilot/ei-02-02.html',
		'<p>תהלים עט7: &quot;כִּי אָכַל אֶת יַעֲקֹב וְאֶת נָוֵהוּ הֵשַׁמּוּ&quot;   --- מדובר על נוה יעקב הטובים והקדושים ביעקב אשר הם השמנה והסלתה של יעקב</p><p>ירמיהו י25: &quot;שְׁפֹךְ חֲמָתְךָ עַל הַגּוֹיִם אֲשֶׁר לֹא יְדָעוּךָ וְעַל מִשְׁפָּחוֹת אֲשֶׁר בְּשִׁמְךָ לֹא קָרָאוּ כִּי אָכְלוּ אֶת יַעֲקֹב וַאֲכָלֻהוּ וַיְכַלֻּהוּ וְאֶת נָוֵהוּ הֵשַׁמּוּ&quot;</p><p> איוב ה3: &quot;אֲנִי רָאִיתִי אֱוִיל מַשְׁרִישׁ וָאֶקּוֹב נָוֵהוּ פִתְאֹם&quot; ---  נָוֵהוּ = הטוב שלו זה יכול להיות ביתו המפואר או משפחתו התומכת -- וכולי</p><p>שמות טו13: &quot;נָחִיתָ בְחַסְדְּךָ עַם זוּ גָּאָלְתָּ נֵהַלְתָּ בְעָזְּךָ אֶל נְוֵה קָדְשֶׁךָ&quot; ---  נְוֵה = קָדְשֶׁךָ</p><p>ירמיהו לא22: &quot;כֹּה אָמַר יהוה צְבָאוֹת אֱלֹהֵי יִשְׂרָאֵל עוֹד יֹאמְרוּ אֶת הַדָּבָר הַזֶּה בְּאֶרֶץ יְהוּדָה וּבְעָרָיו בְּשׁוּבִי אֶת שְׁבוּתָם </p><p>יְבָרֶכְךָ יהוה נְוֵה צֶדֶק הַר הַקֹּדֶשׁ&quot; ---  נְוֵה צֶדֶק = הַר הַקֹּדֶשׁ</p><p>ממש כאשר אומרים נווה-מדבר לאמור החלק הטוב והמובחר שבמדבר</p><p>לכן...</p><p>איכה ב2: &quot; בִּלַּע יהוה וְלֹא חָמַל אֵת כָּל נְאוֹת יַעֲקֹב [והתשובה נמצאת בסוף ככתוב:] חִלֵּל מַמְלָכָה וְשָׂרֶיהָ</p><p>על כן  נְאוֹת יַעֲקֹב =  נְווה יַעֲקֹב --- אשר הם הבכירים ביותר בממלכה = השמנה והסלתה של יעקב</p><p>---------------------------------------------------------------------------------------------------------------------</p><p>פרוש לבאר.......</p><p>בכמה מקומות במקרא מופיע הביטוי נְאוֹת יעקב, ולעיתים הוא מתואר כמי שנאכל, נחרב או נבלע. קריאה שטחית עלולה להוביל למחשבה שמדובר בהשמדה של כלל ישראל, אך עיון מדוקדק מגלה כי “נְאוֹת יעקב” אינם כלל העם אלא החלק הטוב, הנבחר, המובחר והקדוש שביעקב — ממש כמו הביטוי “נווה־מדבר”, המתאר את החלק הטוב שבמדבר.</p><p>הבנה זו מתבררת מתוך רצף פסוקים מקראיים שבהם המילה נוה / נאות מציינת תמיד את הטוב, הקדוש, המובחר, המשובח.</p><p>נוה = הטוב, הקדוש, המשובח</p><p>בכמה פסוקים נוה מופיע במשמעות של מקום קדוש, מובחר או משובח:</p><p>“נְוֵה קָדְשֶׁךָ” (שמות טו13) — נוה = מקום קדוש.</p><p>“נְוֵה צֶדֶק הַר הַקֹּדֶשׁ” (ירמיהו לא22) — נוה צדק = הר הקודש.</p><p>“וְאֶקּוֹב נָוֵהוּ פִתְאֹם” (איוב ה3) — נוהו = הטוב שלו, ביתו המפואר או משפחתו התומכת.</p><p>בכל המקומות הללו, נוה מציין את הטוב ביותר, את החלק הנבחר, את הקדושה.</p><p>לכן ברור כי נְאוֹת יעקב אינם “שדות” או “מרעה” במובן פיזי בלבד, אלא הטובים והקדושים שביעקב, השמנה והסלתה של העם.</p><p>נְאוֹת יעקב = נוה יעקב = בכירי הממלכה</p><p>כעת ניתן להבין את הפסוקים הקשים:</p><p>איכה ב2</p><p>“בִּלַּע יהוה וְלֹא חָמַל אֵת כָּל נְאוֹת יַעֲקֹב… חִלֵּל מַמְלָכָה וְשָׂרֶיהָ.”</p><p>הפסוק עצמו מסביר את משמעות הביטוי:</p><p>נְאוֹת יעקב = שרי הממלכה, הבכירים, הנבחרים, השמנה והסלתה של יעקב.</p><p>החילול הוא של הממלכה ושריה, ולכן “נאות יעקב” הם הבכירים שביעקב, לא כלל העם.</p><p>הגויים אוכלים את “נוהו” — את הטוב שבו</p><p>הפסוקים הבאים מאשרים זאת:</p><p>תהלים עט7</p><p>“כִּי אָכַל אֶת יַעֲקֹב וְאֶת נָוֵהוּ הֵשַׁמּוּ.”</p><p>ירמיהו י25</p><p>“כִּי אָכְלוּ אֶת יַעֲקֹב וַאֲכָלֻהוּ וַיְכַלֻּהוּ וְאֶת נָוֵהוּ הֵשַׁמּוּ.”</p><p>המשמעות הלשונית: נוה = מובחר, קדוש, עליון</p><p>כשם ש“נווה־מדבר” הוא החלק הטוב שבמדבר, כך:</p><p>נוה יעקב = הטוב שביעקב</p><p>נאות יעקב = מובחריו של יעקב</p><p>נוה צדק = הר הקודש</p><p>נוה קדשך = מקום קדוש</p><p>לכן ברור שהביטוי אינו מתאר “מרעה” אלא מעמד רוחני־חברתי עליון.[אליטה של החברה בישראל]</p><p>סיכום: נאות יעקב = השמנה והסלתה של יעקב</p><p>הפסוקים כולם מצביעים על אותה משמעות:</p><p>נוה = הטוב, הקדוש, המובחר</p><p>נוהו = הטוב שבו</p><p>נוה קדשך = מקום קדוש</p><p>נוה צדק = הר הקודש</p><p>נאות יעקב = הבכירים, השרים, הקדושים, הנבחרים</p><p>לכן:</p><p>נְאוֹת יעקב = נוה יעקב = השמנה והסלתה של יעקב, בכירי הממלכה וקדושי העם.</p><p>הפסוקים המתארים את “אכילת” או “השמדת” נאות יעקב אינם מדברים על השמדת כלל ישראל, אלא על פגיעה בבכיריו — במנהיגיו, בקדושיו, בטובו ובמובחרו של העם.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-23 16:39:46'
		)
