		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/ktuv/mgilot/ei-02-02.html',
		'<p>תהלים עט7: &quot;כִּי אָכַל אֶת יַעֲקֹב וְאֶת נָוֵהוּ הֵשַׁמּוּ&quot; --- מדובר על נוה יעקב הטובים והקדושים ביעקב אשר הם השמנה והסלתה של יעקב</p><p>ירמיהו י25: &quot;שְׁפֹךְ חֲמָתְךָ עַל הַגּוֹיִם אֲשֶׁר לֹא יְדָעוּךָ וְעַל מִשְׁפָּחוֹת אֲשֶׁר בְּשִׁמְךָ לֹא קָרָאוּ כִּי אָכְלוּ אֶת יַעֲקֹב וַאֲכָלֻהוּ וַיְכַלֻּהוּ וְאֶת נָוֵהוּ הֵשַׁמּוּ&quot;</p><p>איוב ה3: &quot;אֲנִי רָאִיתִי אֱוִיל מַשְׁרִישׁ וָאֶקּוֹב נָוֵהוּ פִתְאֹם&quot; --- נָוֵהוּ = הטוב שלו זה יכול להיות ביתו המפואר או משפחתו התומכת -- וכולי</p><p>שמות טו13: &quot;נָחִיתָ בְחַסְדְּךָ עַם זוּ גָּאָלְתָּ נֵהַלְתָּ בְעָזְּךָ אֶל נְוֵה קָדְשֶׁךָ&quot; --- נְוֵה = קָדְשֶׁךָ</p><p>ירמיהו לא22: &quot;כֹּה אָמַר יהוה צְבָאוֹת אֱלֹהֵי יִשְׂרָאֵל עוֹד יֹאמְרוּ אֶת הַדָּבָר הַזֶּה בְּאֶרֶץ יְהוּדָה וּבְעָרָיו בְּשׁוּבִי אֶת שְׁבוּתָם</p><p>יְבָרֶכְךָ יהוה נְוֵה צֶדֶק הַר הַקֹּדֶשׁ&quot; --- נְוֵה צֶדֶק = הַר הַקֹּדֶשׁ</p><p>ממש כאשר אומרים נווה-מדבר לאמור החלק הטוב והמובחר שבמדבר</p><p>לכן...</p><p>איכה ב2: &quot; בִּלַּע יהוה וְלֹא חָמַל אֵת כָּל נְאוֹת יַעֲקֹב [והתשובה נמצאת בסוף ככתוב:] חִלֵּל מַמְלָכָה וְשָׂרֶיהָ</p><p>על כן נְאוֹת יַעֲקֹב = נְווה יַעֲקֹב --- אשר הם הבכירים ביותר בממלכה = השמנה והסלתה של יעקב</p><p> -------------------------------------------------------------------------------------------------------------------------------------</p><p>משמעותם של המונחים **נוה** ו־**נאות יעקב** במקרא, מציע כי הם אינם מתארים מרעה פיזי או אזור גאוגרפי בלבד, </p><p>אלא מציינים את **החלק המובחר, הקדוש והנבחר שביעקב** — השמנה והסלתה של העם. </p><p>באמצעות ניתוח לשוני־תיאולוגי של פסוקים ממגוון ספרים (איכה, תהלים, ירמיהו, איוב, שמות), מוצג דפוס עקבי שבו “נוה” משמש לציון *קדושה*, *טוב*, *יופי* ו*מעמד עליון*. </p><p>בהתאם לכך, “נאות יעקב” באיכה ב2 מתפרש ככינוי לשרי הממלכה ולבכירי העם, ולא לכלל ישראל.</p><p>הפסוקים המתארים “אכילה”, “השמדה” או “חילול” של נאות יעקב אינם מתייחסים להשמדת העם כולו, אלא לפגיעה במעמד העליון — במנהיגיו, בקדושיו ובטובו של יעקב. </p><p>ניתוח זה מתיישב עם שימושים נוספים של “נוה” במקרא, כגון “נוה קדשך” ו“נוה צדק”, המחזקים את ההבנה כי מדובר במושג המציין מובחרות וקדושה.</p><p>המסקנה היא כי **נאות יעקב = נוה יעקב = החלק הטוב, הקדוש והמובחר שביעקב**, וכי הבנת משמעות זו חיונית לפרשנות נכונה של פסוקי החורבן וזעם האלוהים במקרא.</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-23 16:54:07'
		)
		;

