		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0215_4.html',
		'<p>אריכות ימים על פי התורה [אנטי-איג\'ינג\']</p><p>------------------------------------------------</p><p>לכבד אב ואם --- כיבוד הורים</p><p>דברים ה15: &quot;כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ כַּאֲשֶׁר צִוְּךָ יהוה אֱלֹהֶיךָ לְמַעַן יַאֲרִיכֻן יָמֶיךָ....... וּלְמַעַן יִיטַב לָךְ עַל הָאֲדָמָה אֲשֶׁר יהוה אֱלֹהֶיךָ נֹתֵן לָךְ&quot;</p><p>משלי יד31: &quot;עֹשֵׁק דָּל חֵרֵף עֹשֵׂהוּ וּמְכַבְּדוֹ חֹנֵן אֶבְיוֹן&quot; ------- ואם אתה מכבד את אביך ואמך אשר הם הוריך עושיך --- אז חנון אביונים</p><p>-</p><p>ליישם באמונה ביראה ובחכמה והבנה ודעת את כל ספר תהילות פרק בכל יום באופן קבוע</p><p>מלכים א ג14: &quot;וְאִם תֵּלֵךְ בִּדְרָכַי לִשְׁמֹר חֻקַּי ומצותי כַּאֲשֶׁר הָלַךְ דָּוִיד אָבִיךָ וְהַאַרַכְתִּי אֶת יָמֶיךָ&quot;.......</p><p>וַיְהִי דָוִד עֹשֶׂה מִשְׁפָּט וּצְדָקָה לְכָל עַמּוֹ --- זה הסוד לאריכות ימים = צְדָקָה וּמִשְׁפָּט</p><p>-</p><p>דברים ה29: &quot;בְּכָל הַדֶּרֶךְ אֲשֶׁר צִוָּה יהוה אֱלֹהֵיכֶם אֶתְכֶם תֵּלֵכוּ --- לְמַעַן תִּחְיוּן וְטוֹב לָכֶם וְהַאֲרַכְתֶּם יָמִים....... בָּאָרֶץ אֲשֶׁר תִּירָשׁוּן&quot;</p><p>שימו לב כי לא מדובר על כאב נצחי באריכות ימים אלא אריכות ימים שהיא עם חיים טובים</p><p>ללכת בכל דרך-יהוה --- וְהַאֲרַכְתֶּם יָמִים....... בָּאָרֶץ אֲשֶׁר תִּירָשׁוּן = בָּאָרֶץ אֲשֶׁר תִּירָשׁוּן? בָּאָרֶץ אֲשֶׁר תִירשׁ בה --- לשתות כל שבת בקידוש</p><p>בברכת יצחק ליעקב בספר בראשית פרק כז כתוב:</p><p>(כח) וְיִתֶּן לְךָ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ וְרֹב דָּגָן וְתִירשׁ:</p><p>הארכת ימים בארץ אשר תִירשׁ [תירוש] בה</p><p>אכן על פי מחקרים התירוש בארצך [בגופך] מאריך ימים או בלשון החוקרים &quot;מעכב תהליכי הזדקנות&quot;</p><p>סוף דבר</p><p>ספר-מקרא-הקודש מציג מודל של אנטי־אייג’ינג רוחני:</p><p>אריכות ימים הנובעת ממערכת מוסרית־רוחנית הכוללת:</p><p>ללכת בדרך-יהוה לעשות צדקה ומשפט</p><p>ובמיוחד לכבד את ההורים בעשותך צדקה ומשפט אביונים לחנון</p><p>וכן לשתות תירוש בקידוש יום השבת לברכה</p><p>קריאת תהילים בקביעות</p><p>המסר המקראי על פי תורת-יהוה ברור:</p><p>אריכות ימים איננה רק עניין גופני — היא תוצאה של חיים מוסריים קדושים ומלאי חסד.</p><p>--------------------------------------------------------------------------------------------------</p><p>תהלים כא5: &quot;חַיִּים שָׁאַל מִמְּךָ נָתַתָּה לּוֹ אֹרֶךְ יָמִים עוֹלָם וָעֶד&quot;</p><p>תהלים כג6: &quot;אַךְ טוֹב וָחֶסֶד יִרְדְּפוּנִי כָּל יְמֵי חַיָּי וְשַׁבְתִּי בְּבֵית יהוה לְאֹרֶךְ יָמִים&quot;</p><p>תהלים צא16: &quot;אֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ וְאַרְאֵהוּ בִּישׁוּעָתִי&quot;</p><p>תהלים צג5: &quot;עֵדֹתֶיךָ נֶאֶמְנוּ מְאֹד לְבֵיתְךָ נַאֲוָה קֹדֶשׁ יהוה לְאֹרֶךְ יָמִים&quot; </p><p>איוב יב12: &quot;בִּישִׁישִׁים חָכְמָה וְאֹרֶךְ יָמִים תְּבוּנָה&quot; </p><p>משלי ג2: &quot;כִּי אֹרֶךְ יָמִים וּשְׁנוֹת חַיִּים וְשָׁלוֹם יוֹסִיפוּ לָךְ&quot; </p><p>משלי ג16: &quot;אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאולָהּ עֹשֶׁר וְכָבוֹד&quot; </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-23 18:30:24'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

