		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2810_4.html',
		'<p>משלי יא31: &quot;הֵן צַדִּיק בָּאָרֶץ יְשֻׁלָּם אַף כִּי רָשָׁע וְחוֹטֵא&quot;</p><p>תהלים צז11: &quot;אוֹר זָרֻעַ לַצַּדִּיק וּלְיִשְׁרֵי לֵב שִׂמְחָה&quot;</p><p>ישעיהו מ10: &quot;הִנֵּה אֲדֹנָי יהוה בְּחָזָק יָבוֹא וּזְרֹעוֹ מֹשְׁלָה לוֹ הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו&quot;</p><p>ישעיהו סב11: &quot;הִנֵּה יהוה הִשְׁמִיעַ אֶל קְצֵה הָאָרֶץ אִמְרוּ לְבַת צִיּוֹן הִנֵּה יִשְׁעֵךְ בָּא הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו&quot;</p><p>הֵן צַדִּיק בָּאָרֶץ יְשֻׁלָּם =  הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו [וכן כל ההולך בדרכי-יהוה] =  וּלְיִשְׁרֵי לֵב שִׂמְחָה</p><p>---------------------------------------------------------------------------------------------------------------------------</p><p>אז מדוע רבנים מתעתעים בציבור ואומרים כי הצדיק סובל מַכְאוֹבִים בעולם הזה ואין שכר הצדיק בעולם הזה?</p><p>והסיבה היא כי נדמה לרבנים הרשעים שהם צדיקים --- אף כי הם רשעים ואינם מבינים כי.....</p><p>תהלים לב10: &quot;רַבִּים מַכְאוֹבִים לָרָשָׁע וְהַבּוֹטֵחַ ביהוה חֶסֶד יְסוֹבְבֶנּוּ&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-24 02:59:21'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t26b2_1.html',
		'<p>משלי יא31: &quot;הֵן צַדִּיק בָּאָרֶץ יְשֻׁלָּם אַף כִּי רָשָׁע וְחוֹטֵא&quot;</p><p>תהלים צז11: &quot;אוֹר זָרֻעַ לַצַּדִּיק וּלְיִשְׁרֵי לֵב שִׂמְחָה&quot;</p><p>ישעיהו מ10: &quot;הִנֵּה אֲדֹנָי יהוה בְּחָזָק יָבוֹא וּזְרֹעוֹ מֹשְׁלָה לוֹ הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו&quot;</p><p>ישעיהו סב11: &quot;הִנֵּה יהוה הִשְׁמִיעַ אֶל קְצֵה הָאָרֶץ אִמְרוּ לְבַת צִיּוֹן הִנֵּה יִשְׁעֵךְ בָּא הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו&quot;</p><p>הֵן צַדִּיק בָּאָרֶץ יְשֻׁלָּם =  הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו [וכן כל ההולך בדרכי-יהוה] =  וּלְיִשְׁרֵי לֵב שִׂמְחָה</p><p>---------------------------------------------------------------------------------------------------------------------------</p><p>אז מדוע רבנים מתעתעים בציבור ואומרים כי הצדיק סובל מַכְאוֹבִים בעולם הזה ואין שכר הצדיק בעולם הזה?</p><p>והסיבה היא כי נדמה לרבנים הרשעים שהם צדיקים --- אף כי הם רשעים ואינם מבינים כי.....</p><p>תהלים לב10: &quot;רַבִּים מַכְאוֹבִים לָרָשָׁע וְהַבּוֹטֵחַ ביהוה חֶסֶד יְסוֹבְבֶנּוּ&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-24 02:59:57'
		)
		;

