		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0526_3.html',
		'<p> אני דיין איש דעת-אלהים כעץ-הדעת וחש ורואה איך בני האדם מתאוים לאכול פרי-קֹדֶשׁ-זרעי</p><p>ירמיהו ב3: &quot;קֹדֶשׁ יִשְׂרָאֵל ליהוה רֵאשִׁית תְּבוּאָתֹה כָּל אֹכְלָיו יֶאְשָׁמוּ רָעָה תָּבֹא אֲלֵיהֶם נְאֻם יהוה&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-24 05:00:54'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2821_2.html',
		'<p>מאת דיין שם --- עבד-יהוה ומשיחו</p><p>אני מורה לתורה משה דַיָּן שר יהוה צְבָאוֹת מְפַקֵּד צְבָא מִלְחָמָה.......</p><p>ישעיהו יג4: &quot;קוֹל הָמוֹן בֶּהָרִים דְּמוּת עַם רָב קוֹל שְׁאוֹן מַמְלְכוֹת גּוֹיִם נֶאֱסָפִים יהוה צְבָאוֹת מְפַקֵּד צְבָא מִלְחָמָה&quot;.......</p><p>-</p><p>במדבר לב6: &quot;וַיֹּאמֶר מֹשֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן הַאַחֵיכֶם יָבֹאוּ לַמִּלְחָמָה וְאַתֶּם תֵּשְׁבוּ פֹה&quot;</p><p>ארץ ישראל ארץ מלחמות היא !! ואם תדעו לנתב המלחמה לכבוד אלהים אז יבוא שלום</p><p>עליכם לבחור .......</p><p>בין מלחמה פנימית [גבורה על יצר הרע] </p><p>לבין מלחמה חיצונית [בצוררי-ישראל]</p><p>-</p><p>ואגיד לכם אמת כי אם תבחרו במלחמה הפנימית אז יבוא שלום על ישראל</p><p>כי מי שנלחם מלחמות פנימיות=מלחמות יהוה אז יש לו שלום מכל עבר מסביב</p><p>רב לכם קציני וקברניטי ישראל בהנהגה כי אם יש מלחמות חיצוניות טרור ופיגועים זה רק בגלל שלא נלחמתם בפנים פנימה בתוככם</p><p>--------------------------------------------------------------------------------------------------</p><p>פרוש לבאר</p><p>כִּי לֹא לָכֶם הַמִּלְחָמָה כִּי לֵאלֹהִים --- כִּי מֵהָאֱלֹהִים הַמִּלְחָמָה</p><p>שמות יז16: &quot;וַיֹּאמֶר כִּי יָד עַל כֵּס יָהּ מִלְחָמָה ליהוה בַּעֲמָלֵק מִדֹּר דֹּר&quot;</p><p>מִלְחָמָה ליהוה בַּעֲמָלֵק מִדֹּר דֹּר = היא מלחמה לנצח של רוח אלהים</p><p>הארץ הזו תמיד דרשה מאדם לב חזק</p><p>הארץ הזו תמיד דרשה מאבק פנימי</p><p>הארץ הזו תמיד דרשה עמידה מול קושי</p><p>הארץ הזו תמיד דרשה אחריות הדדית</p><p>המלחמות של המקרא אינן רק מלחמות פיזיות.</p><p>הן מלחמות של תכונות אלהים:</p><p>מוסר</p><p>צדק</p><p>אמונה</p><p>אמת</p><p>לב</p><p>שליחות</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-24 07:20:00'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

