		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/ktuv/mgilot/ei-02-01.html',
		'<p>איכה ב1: &quot; אֵיכָה יָעִיב בְּאַפּוֹ יהוה אֶת בַּת צִיּוֹן הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל וְלֹא זָכַר הֲדֹם רַגְלָיו בְּיוֹם אַפּוֹ?</p><p>https://tora.quest/tnk1/kma/qjrim1/hdm.html?no_cache=1784884052</p><p>איכה ב1: &quot;  וְלֹא זָכַר הֲדֹם רַגְלָיו בְּיוֹם אַפּוֹ? ולא זכר את הקדושים בישראל אשר מתחתיו - הֲדֹם רַגְלָיו אלה משרתיו</p><p>בראשית נ19: &quot;וַיֹּאמֶר אֲלֵהֶם יוֹסֵף אַל תִּירָאוּ כִּי הֲתַחַת אֱלֹהִים אָנִי&quot; --- אָנִי יוֹסֵף הֲדֹם רַגְלָיו של האלהים אשר מעליי</p><p>תהלים מב7: &quot;אֱלֹהַי עָלַי .......נַפְשִׁי תִשְׁתּוֹחָח עַל כֵּן אֶזְכָּרְךָ מֵאֶרֶץ יַרְדֵּן וְחֶרְמוֹנִים מֵהַר מִצְעָר&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-24 09:11:51'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1302_0.html',
		'<p>תהלים לו11: &quot;מְשֹׁךְ חַסְדְּךָ לְיֹדְעֶיךָ וְצִדְקָתְךָ לְיִשְׁרֵי לֵב&quot;</p><p>מי שאינו מבין ברגש את חסדי-האל שעשה עימו אינו יודע את האלהים</p><p>מי שאינו מבין ברגש את צדקת-האל שעשה עימו אינו באמת ישר-לב</p><p>-</p><p>פרוש לבאר.......</p><p>תהלים ל&quot;ו י&quot;א אומר: “מְשֹׁךְ חַסְדְּךָ לְיֹדְעֶיךָ וְצִדְקָתְךָ לְיִשְׁרֵי־לֵב”. פסוק זה מלמד כי ידיעת האל אינה ידיעה שכלית בלבד, אלא ידיעה רגשית וחווייתית. </p><p>מי שאינו חש בליבו את חסדי האל שעשה עמו – אינו יודע את האל באמת, משום שהקשר עם האל נבנה מתוך הכרת הטוב, הודיה פנימית ותחושת חסד שממלאת את הלב. </p><p>באותו אופן, מי שאינו מרגיש בליבו את צדקת האל – אינו ישר־לב באמת, כי יושר הלב אינו רק מוסר חיצוני או התנהגות תקינה, אלא היכולת להרגיש את הצדק האלוהי ולכוון את הלב אליו. </p><p>הפסוק מלמד שהחסד והצדקה של האל נמשכים אל מי שליבו פתוח, רגיש ומסוגל להכיר בטוב האל ולהרגיש אותו מבפנים. ידיעת האל ויושר הלב הם מצבים פנימיים של רגש חי, </p><p>לא רק מחשבה או לימוד. מי שמרגיש את חסד האל – יודע את האל; מי שמרגיש את צדקת האל – ישר־לב. ------- הללו-יה</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-24 15:14:00'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1302_0.html',
		'<p>תהלים לו11: &quot;מְשֹׁךְ חַסְדְּךָ לְיֹדְעֶיךָ וְצִדְקָתְךָ לְיִשְׁרֵי לֵב&quot;</p><p>מי שאינו מבין ברגש את חסדי-האל שעשה עימו אינו יודע את האלהים</p><p>מי שאינו מבין ברגש את צדקת-האל שעשה עימו אינו באמת ישר-לב</p><p>פסוק תהלים ל&quot;ו י&quot;א אומר: “מְשֹׁךְ חַסְדְּךָ לְיֹדְעֶיךָ וְצִדְקָתְךָ לְיִשְׁרֵי־לֵב”. פסוק זה מציג תפיסה רוחנית עמוקה שלפיה ידיעת האל אינה ידיעה שכלית בלבד, </p><p>אלא ידיעה רגשית וחווייתית הנובעת מתוך לב פתוח ומרגיש. מי שאינו חש בליבו את חסדי האל שעשה עמו – אינו יודע את האל באמת, </p><p>משום שהקשר עם האל נבנה מתוך הכרת הטוב, הודיה פנימית ותחושת חסד שממלאת את הלב. </p><p>ידיעת האל על פי המקרא היא חוויה של קרבה, של רגש חי ושל תחושת חסד המושך את האדם אל האל ומחזק את אמונתו.</p><p>באותו אופן, מי שאינו מרגיש בליבו את צדקת האל – אינו ישר־לב באמת. יושר הלב אינו רק מוסר חיצוני או התנהגות תקינה, אלא היכולת להרגיש את הצדק האלוהי ולכוון את הלב אליו.</p><p> ישר־לב הוא אדם שמבין את הצדק לא רק בשכלו אלא גם ברגשותיו, אדם שמרגיש את האמת האלוהית ומיישר את דרכיו על פיה. </p><p>צדקת-האלהים נמשכת אל מי שליבו נקי, רגיש ומסוגל להכיר בטוב האל ולהרגיש אותו מבפנים.</p><p>הפסוק מלמד שהחסד והצדקה של האל אינם תופעות חיצוניות בלבד, אלא כוחות רוחניים הנמשכים אל האדם שמוכן לקבלם בליבו. </p><p>ידיעת האל ויושר הלב הם מצבים פנימיים של רגש חי, לא רק מחשבה או לימוד. מי שמרגיש את חסד האל – יודע את האל; מי שמרגיש את צדקת האל – ישר־לב. ------- הללו-יה</p><p></p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-24 15:52:20'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

