		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0518_3.html',
		'<p>שמואל א ג17: &quot;וַיֹּאמֶר מָה הַדָּבָר אֲשֶׁר דִּבֶּר אֵלֶיךָ אַל נָא תְּכַחֵד מִמֶּנִּי כֹּה יַעֲשֶׂה לְּךָ אֱלֹהִים וְכֹה יוֹסִיף אִם תְכַחֵד מִמֶּנִּי דִּבֶּר מִכָּל הַדָּבָר אֲשֶׁר דָּבָר אֵלֶיךָ&quot;</p><p>שמואל א ג18: &quot;וַיַּגֶּד לוֹ שְׁמוּאֵל אֶת כָּל הַדְּבָרִים [שחפני ופנחס בניו של עלי ימותו] וְלֹא כִחֵד מִמֶּנּוּ וַיֹּאמַר יהוה הוּא הַטּוֹב בְּעֵינָו יַעֲשֶׂה&quot; --- </p><p>--- זה משפט של כהן גדול צדיק המזכיר לטובה את ראש אבותיו הכהנים הלא הוא אהרן הכהן הגדול כהן הראש אשר לא התלונן </p><p>ולא אמר מילה רעה כאשר ראה במו עיניו את שני בניו נדב ואביהו נשרפים באש למוות וידום אהרן</p><p>ויקרא י3: &quot;וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן הוּא אֲשֶׁר דִּבֶּר יהוה לֵאמֹר בִּקְרֹבַי אֶקָּדֵשׁ וְעַל פְּנֵי כָל הָעָם אֶכָּבֵד וַיִּדֹּם אַהֲרֹן&quot;</p><p>-</p><p>פרוש לבאר.......</p><p>הפסוקים בשמואל א’ ג’ ובפרשת נדב ואביהו מלמדים כי מנהיגות רוחנית אמיתית נבחנת ביכולת לקבל את דבר יהוה גם כשהוא קשה. </p><p>עלי הכהן הגדול, כמו אהרן הכהן לפניו, עומד מול דבר יהוה בענווה ובקבלת דין. אין הוא מתווכח, אין הוא מתמרד, ואין הוא מבקש לשנות את הגזרה. </p><p>הוא מכיר בכך שהאמת של האלהים גבוהה מן האדם, ועל האדם להכניע את ליבו בפני רצון יהוה. </p><p>זהו מודל של מנהיגות רוחנית שאינה נמדדת בכוח או בסמכות, אלא ביכולת להקשיב, לקבל, ולהישאר נאמנה לאמת האלהים גם כאשר היא דורשת הקרבה אישית.</p><p>-</p><p>הכותב הוא דיין שם --כהן-יהוה --- הוא מורה לתורה משה דין</p><p> https://tora.quest/tnk1/daian</p><p>           דַיָּן שֵׁם           </p><p>        מְשָׁרֵת יהוה        </p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-26 09:47:46'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

