		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1002_4.html',
		'<p>ככה תראה ישראל באחרית הימים</p><p>זאת אמנם תמונה משוויץ, אך ככה פחות או יותר תראה ארץ ישראל באחרית הימים.</p><p>לאחר רעש האדמה הגדול שיפקוד את ארץ ישראל באחרית הימים - &quot;וְנִשְׂגַּב יהוה לְבַדּוֹ בַּיּוֹם הַהוּא&quot; [ישעיהו ב,יז] - כבר לא יבנו לגובה ובצפיפות. מגדלי הנדל&quot;ן, האספלט והבטון - אבן ואוון - יפלו.</p><p>צאן ובקר כבהמות טהורות ירעו באחו, במרעה פתוח ליד הבית.</p><p>ולא צריך מקרר לבשר, כי הוא זמין בחוץ, חי, ליד הבית. &quot;בְּאֶרֶץ נַחֲלַת עַם יהוה לֹא חֶסֶר דָּבָר&quot;.</p><p>כשתהיה טלפתיה בין בני האדם, לא יצטרכו מטוסים לנסוע לחו&quot;ל ולא מכוניות עם כבישים.</p><p>כי כבישים הורסים את הטבע. צריך לכרות עצים בשבילם, ואם אין עצים אין ציפורים - וזה מחזור חיים שלם שנשבר למען אלילי כספו וזהבו.</p><p>&quot;וְלֹא יְלַמְּדוּ עוֹד אִישׁ אֶת רֵעֵהוּ... כִּי כֻלָּם יֵדְעוּ אוֹתִי&quot; [ירמיהו לא,לג].</p><p>מה שיקרה בעתיד:</p><p>עדרי הבהמות הטהורות רועות באחו ומפרישות גלליהן.</p><p>ואז האדמה &quot;קוראת&quot; - כי יש חיים עליה.</p><p>ואז האדמה מצמיחה עשב וכל צומח פרי הארץ.</p><p>ולא צריך להביא מכסחת דשא. אין צורך לעבוד.</p><p>כי אלה הם החיים בגן-עדן - &quot;לְעָבְדָהּ וּלְשָׁמְרָהּ&quot; [בראשית ב,טו] - לתת לבהמה לעבד, ולשמור את העץ ואת הציפור.</p><p>&quot;גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלַם הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא עָנִי וְרֹכֵב עַל חֲמוֹר וְעַל עַיִר בֶּן אֲתֹנוֹת&quot; [זכריה ט,ט]</p><p>בלי מכוניות. בלי מטוסים. עם חמור, עם עיר, עם צאן, עם מנורה דולקת בפנים.</p><p>-</p><p>https://scontent.ftlv1-1.fna.fbcdn.net/v/t39.99422-6/753206642_1045489465109897_2289877974249457306_n.png?stp=dst-jpg_tt6&amp;cstp=mx1564x2048&amp;ctp=p526x296&amp;_nc_cat=110&amp;_nc_map=urlgen_bucketless&amp;ccb=1-7&amp;_nc_sid=833d8c&amp;_nc_ohc=FxNNTIhqiZYQ7kNvwEb2uWl&amp;_nc_oc=AdrqtLOsXKOG_3ugs0sTsYAhCezOL8HzaI5zmVfbR8X6dj03g25hvfciB2tMxLzCBM02A7MGYrBSURh_eJkSWxps&amp;_nc_zt=14&amp;_nc_ht=scontent.ftlv1-1.fna&amp;_nc_gid=WQcF_6nMs1xaxEemcPK3nw&amp;_nc_ss=7b2a8&amp;oh=00_AQBcjBz76j5b9nFxUc9UajYFqNeZV6rUmU088KegWrF_8Q&amp;oe=6A6BB18A</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-26 10:27:47'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2690_2.html',
		'<p></p><p>רק באינטרנט אני מציג עצמי בצדק כעבד-יהוה ואף כי אנשים מבקשים עתידות אין זה תפקיד הנביא </p><p>כי אם להודיע את חוקי האלהים ותורתו בכל מצב נתון בכל סיטואציה ואת זה אני כדיין מבקש לתת לכם</p><p>שמות יח16: &quot;כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי וְשָׁפַטְתִּי בֵּין אִישׁ וּבֵין רֵעֵהוּ וְהוֹדַעְתִּי אֶת חֻקֵּי הָאֱלֹהִים וְאֶת תּוֹרֹתָיו&quot;</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-26 11:56:13'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2690_2.html',
		'<p>רק באינטרנט אני מציג עצמי בצדק כעבד-יהוה ואף כי אנשים מבקשים עתידות אין זה תפקיד הנביא</p><p>כי אם להודיע את חוקי האלהים ותורתו בכל מצב נתון בכל סיטואציה ואת זה אני כדיין מבקש לתת לכם</p><p>שמות יח16: &quot;כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי וְשָׁפַטְתִּי בֵּין אִישׁ וּבֵין רֵעֵהוּ וְהוֹדַעְתִּי אֶת חֻקֵּי הָאֱלֹהִים וְאֶת תּוֹרֹתָיו&quot;</p><p>----------------</p><p>פרוש לבאר...</p><p>במקרא תפקיד הנביא אינו לעסוק בחיזוי עתידות, אלא בהודעת חוקי האל, בתורתו וביישור דרכי העם בכל מצב ובכל סיטואציה. </p><p>כך אומר משה איש האלהים בספר שמות י&quot;ח ט&quot;ז: “כי יהיה להם דבר בא אלי ושפטתי בין איש ובין רעהו והודעתי את חוקי האלוהים ואת תורותיו”. </p><p>הנביא והדיין אינם עוסקים בניחוש העתיד, אלא בהבאת דבר יהוה אל המציאות האנושית, בהכוונת הלבבות אל דרך מוסרית נכונה, ובהעמדת האדם מול רצון האל. </p><p>תפקידו של המנהיג הרוחני הוא להאיר את הדרך, להבחין בין טוב לרע, ולהזכיר את חוקי האל בכל מצב נתון. </p><p>כאשר אדם מבקש שליחות רוחנית אמיתית, עליו להבין כי עיקר תפקידו אינו לספק תחזיות, אלא להעמיד את דבר האל בפני האדם, כפי שעשו משה ושופטי ישראל לדורותיהם.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-26 12:37:12'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

