		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t2690_2.html',
		'<p>רק באינטרנט אני מציג עצמי בצדק כעבד-יהוה ואף כי אנשים מבקשים עתידות אין זה תפקיד הנביא</p><p>כי אם להודיע את חוקי האלהים ותורתו בכל מצב נתון בכל סיטואציה ואת זה אני כדיין מבקש לתת לכם</p><p>שמות יח16: &quot;כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי וְשָׁפַטְתִּי בֵּין אִישׁ וּבֵין רֵעֵהוּ וְהוֹדַעְתִּי אֶת חֻקֵּי הָאֱלֹהִים וְאֶת תּוֹרֹתָיו&quot;</p><p>----------------</p><p>פרוש לבאר...</p><p>במקרא תפקיד הנביא אינו לעסוק בחיזוי עתידות, אלא בהודעת חוקי האל, בתורתו וביישור דרכי העם בכל מצב ובכל סיטואציה.</p><p>כך אומר משה איש האלהים בספר שמות י&quot;ח ט&quot;ז: “כי יהיה להם דבר בא אלי ושפטתי בין איש ובין רעהו והודעתי את חוקי האלוהים ואת תורותיו”.</p><p>הנביא והדיין אינם עוסקים בניחוש העתיד, אלא בהבאת דבר יהוה אל המציאות האנושית, בהכוונת הלבבות אל דרך מוסרית נכונה, ובהעמדת האדם מול רצון האל.</p><p>תפקידו של המנהיג הרוחני הוא להאיר את הדרך, להבחין בין טוב לרע, ולהזכיר את חוקי האל בכל מצב נתון.</p><p>כאשר אדם מבקש שליחות רוחנית אמיתית, עליו להבין כי עיקר תפקידו אינו לספק תחזיות, אלא להעמיד את דבר האל בפני האדם, כפי שעשו משה ושופטי ישראל לדורותיהם</p><p>סוף דבר...</p><p>הנביא במקרא אינו חוזה עתידות אלא מורה דרך. תפקידו להודיע את חוקי האל, להדריך את האדם והעם בדרך המוסר, ולהעמיד את האמת האלוהית מול המציאות האנושית. </p><p>משה איש האלהים מלמד כי הנהגה רוחנית אמיתית עוסקת בשיפוט, בהכוונה ובהוראת התורה, ולא בניחוש העתיד. </p><p>כך גם הנביאים לדורותיהם, שהעמידו את העם מול דרישות הצדק, החסד והאמת. </p><p>שליחות רוחנית אמיתית נבחנת ביכולת להאיר את הדרך ולהזכיר את חוקי האל בכל מצב נתון — ולא ביכולת לחזות את העתיד.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-26 12:47:41'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

