		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/tora/jmot/jm-1821.html',
		'<p>השמאל איבדו יהדותם לחלוטין והימין לעתים ימין-שקר</p><p>כמובן בהכללה גסה וגורפת ותמיד יש יוצאים מהכלל --- נא הבינו...</p><p>אני לא מכבד ימניים שרוצים את השטחים כשכן רע שלא מוותר </p><p>שכן ימני כזה יריב איתך במחלוקת על מקום חנייה משותפת </p><p>אני מכבד מתנחלים שאוהבים את נחלת ישראל מתוך קודש </p><p>על כן אני בוחר בציונות הדתית של בצלאל סמוטריץ</p>',
		'115934331744503251746',
		'DAIAN SHEM',
