		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t0215_4.html',
		'<p>פרי עץ היער-יעיר אותך ועל כן מועדו לעת זריחת השמש באור-הבקר</p><p>למשל נס-קפה מתאים לַבֹּקֶר [תרתי משמע] לאור-בֹּקֶר ולחלב-בָּקָר</p><p>ופרי האדמה הפירות הנמוכים הקרובים לאדמה &quot;צמודי הקרקע&quot; מועדם לערב</p><p>למשל אבטיח ומלון או מלפפון ועגבניה מועדם בערב וישמרו על נוזלי הגוף ככה שלא צריך לשתות מים בערב וזה ימנע ממך לקום באמצע הלילה להשתין</p>',
