		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1404_0.html',
		'<p>אלהים מדבר עם דיין דרך הלב כי לדיין לֵב שֹׁמֵעַ תודה לאל --- וַיֵּלְכוּ עִמּוֹ הַחַיִל אֲשֶׁר נָגַע אֱלֹהִים בְּלִבָּם</p><p>במהלך חייו של משיח בן-דוד המלך הלא הוא המלך שלמה ביקש כדבר הבא...ככתוב בספר.......</p><p>מלכים א ג9: &quot;וְנָתַתָּ לְעַבְדְּךָ לֵב שֹׁמֵעַ לִשְׁפֹּט....... אֶת עַמְּךָ לְהָבִין בֵּין טוֹב לְרָע כִּי מִי יוּכַל לִשְׁפֹּט אֶת עַמְּךָ הַכָּבֵד הַזֶּה&quot;</p><p>אחיי ---- דיין כבר נולד עם לֵב שֹׁמֵעַ לִשְׁפֹּט --- הלא דיין הוא --- דיין שם</p><p>https://tora.quest/tnk1/daian</p><p>דַיָּן שֵׁם</p><p>מְשָׁרֵת יהוה</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-28 01:46:19'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

