		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1502_2.html',
		'<p> </p><p>אל תתרשמו משפת חלקות של רבנים גם השטן יודע את כל התורה</p><p>הביטו לדבר אחד האם הם לחברה תורמים או מתרימים [את החברה]</p><p>-</p><p>אני לא קונה את שפת החלקות של הרבנים. ידע תורני לא הופך אף אחד לאדם ישר — גם השטן יודע את כל התורה.</p><p>מי שמנופף בסמכות דתית אבל בפועל רק מתרִים את החברה במקום לתרום לה, משתמש בתורה כמסך עשן.</p><p>בעיניי, מי שלא נותן ערך אמיתי לחברה אלא רק שואב ממנה — לא ראוי לכבוד ולא לאמון, בלי קשר לכיפה או לתואר שהוא נושא.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-28 13:15:45'
		)
		;

SET character_set_client=utf8mb3;
SET character_set_connection=utf8mb3;

		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
