		INSERT INTO tguvot (parent,body,userid,username,created_at) VALUES (
		'tnk1/messages/prqim_t1502_1.html',
		'<p>יש אנשים המכנים את עצמם “רוחניים”, אך הרוחניות שלהם אינה אלא מסכה דקה שמסתירה פצע עמוק. </p><p>הם אינם מגיעים אל האל מתוך אהבה, אלא מתוך מצוקה; לא מתוך חיפוש אמת, אלא מתוך חיפוש מפלט.</p><p>יש גם מי שמניחים תפילין וחשים כאילו ביצעו פעולה שמחייבת את האל להגיב. זהו ניסיון פילוסופי שקוף להפוך את האל למנגנון — כאילו האל הוא מערכת שניתן להפעיל באמצעות טקס.</p><p>אך האל שוכן המרום אינו מניח תפילין. האל אינו זקוק לסמל, אינו זקוק לטקס, אינו זקוק לפעולה טכנית.</p><p>האל עושה צדקה ומשפט — וזו דרכו; ועל האדם מצוּוה ללכת בדרכיו.</p><p>צדקה ומשפט הם פעולות שמשנות את המציאות, שמתקנות עוול, שמחייבות את האדם לצאת מעצמו.</p><p>לעומת זאת, הנחת תפילין היא פעולה טכנית. היא יכולה להיות עמוקה, אך היא אינה מוסרית כשלעצמה. </p><p>היא אינה צדקה ואינה משפט; היא אינה דורשת מהאדם להתבונן על עצמו, להכיר בפגיעותיו, או לשאת באחריות למעשיו.</p><p>כאשר אדם משתמש בטקס כדי להרגיש שהוא “קנה” את האל, הוא מבצע הונאה פילוסופית: הוא מחליף את המוסר בסמל, את האחריות בפעולה טכנית, את האמת בתחושת זכאות.</p><p>זו בריחה מן המציאות, לא התמודדות איתה.!! הדת, במובנה העמוק, אינה מערכת של טקסים אלא מערכת של משמעות.</p><p>וכאשר הטקס הופך להיות תחליף למשמעות — הדת מתפוררת, והאדם מתפורר איתה.</p><p>מול אתגרי קיום גדולים — בין אם הם היסטוריים, חברתיים או רוחניים — רק צדקה ומשפט מחזיקים את האדם ואת החברה.</p><p>טקסים אינם תחליף למוסר, ואינם תחליף לאחריות.!! כי האל אינו מבקש מן האדם להניח סימן על גופו — אלא להניח אמת בלבבו.</p>',
		'115934331744503251746',
		'DAIAN SHEM',
		'2026-07-29 07:25:00'
		)
		;

